// Üretilen dosya: tool/ozgun/uret.py. Fizik ve Astronomi · Basit harmonik hareket, evrensel kütleçekim, Kepler yasaları ve uydu yörüngeleri (yay-sarkaç periyodu, kaçış hızı, yer eşzamanlı yörünge) (zor).
const ozPhysics16Zor = <(String, String, List<String>, String)>[
  ('Harmonik salınım yapan bir cismin hız-uzanım (v-x) grafiği dik koordinat düzleminde çizildiğinde hangi geometrik şekil ortaya çıkar?', 'Merkezi başlangıç noktasında yer alan kapalı bir elips eğrisi', ['Orijinden geçen negatif eğimli düz bir doğru parçası', 'Tepe noktası maksimum hızda bulunan ters dönmüş bir parabol', 'Eksenlere asimptotik yaklaşan iki kollu bir hiperbol grafiği'], 'v^2 = omega^2 * (A^2 - x^2) bağıntısı düzenlenirse (x^2 / A^2) + (v^2 / v_max^2) = 1 denklemi elde edilir; bu da merkezi orijinde olan bir elips belirtir.'),
  ('Genliği A, açısal frekansı omega olan basit harmonik harekette, hız büyüklüğü ile ivme büyüklüğünün sayısal olarak birbirine eşitlendiği konumda tanjant faz açısı veya omega-uzanım ilişkisi düşünüldüğünde, x uzanımı hangi ifadeye eşittir?', 'A bölü karekök içinde bir artı omega kare', ['A çarpı omega bölü bir artı omega ifadesi', 'A bölü parantez içinde bir artı omega değeri', 'A çarpı karekök içinde omega eksi bir farkı'], '|v| = |a| koşulu yazılırsa omega * karekök(A^2 - x^2) = omega^2 * x olur. Sadeleştirip karesi alınırsa A^2 - x^2 = omega^2 * x^2 -> A^2 = x^2(1 + omega^2) -> x = A / karekök(1 + omega^2) çıkar.'),
  ('Basit harmonik hareket yapan bir kızağın bir tam periyot boyunca ortalama sürati (toplam alınan yol / periyot), maksimum süratinin (v_max) kaç katına eşittir?', 'İki bölü pi katına karşılık gelen oran', ['Bir bölü iki katına eşit aritmetik ortalama', 'Bir bölü kök iki katı olan etkin değer', 'Pi bölü dört katına ulaşan geometrik oran'], 'Toplam yol 4A olduğundan ortalama sürat v_ort = 4A / T\'dir. Maksimum sürat ise v_max = 2*pi*A / T\'dir. Oranlandığında v_ort / v_max = (4A/T) / (2*pi*A/T) = 2 / pi bulunur.'),
  ('Yatay düzlemde sürtünmesiz salınan bir cismin üzerine konulan küçük bir madeni para, cisimle arasındaki statik sürtünme katsayısı mu_s iken kaymadan birlikte harmonik hareket yapıyor. Salınım frekansı f sabit tutularak para kaymadan ulaşılabilecek en büyük genlik A_max nedir?', 'Mu_s çarpı g bölü dört pi kare f kare', ['Mu_s çarpı g bölü iki pi çarpı f', 'Dört pi kare f kare bölü mu_s çarpı g', 'Karekök içinde mu_s çarpı g bölü f'], 'Parayı ivmelendiren kuvvet statik sürtünmedir: m * a_max <= mu_s * m * g. Buradan (2*pi*f)^2 * A <= mu_s * g ve A_max = (mu_s * g) / (4 * pi^2 * f^2) bulunur.'),
  ('Düşey düzlemde kendi ekseni etrafında salınım yapan bir piston tablası düşeyde 4 Hz frekansla basit harmonik hareket icra ediyor. Tablanın üzerindeki küçük bir vidanın yüzeyle temasını kaybetmemesi için genlik en fazla kaç metre olabilir (g = 10 m/s^2, pi^2 = 10 alınız)?', 'Bir bölü altmış dört metre sınır değeri', ['Bir bölü on altı metre kritik genlik', 'Bir bölü otuz iki metre maksimum uzanım', 'Bir bölü sekiz metre temas kopma sınırı'], 'Üst uç noktada vidanın tabladan ayrılmaması için maksimum aşağı yönlü ivme yerçekimi ivmesini aşmamalıdır: a_max <= g -> 4 * pi^2 * f^2 * A <= g -> 4 * 10 * 16 * A <= 10 -> 640 A <= 10 -> A <= 1/64 m.'),
  ('Basit harmonik harekette ivmenin zamana göre türevi olan \'sarsım\' (jerk, j = da/dt) büyüklüğü salınım yörüngesinin hangi noktasında en büyük değerine ulaşır?', 'Cismin denge merkezinden geçtiği sıfır uzanım noktasında', ['Hızın anlık olarak sıfırlandığı genlik sınırlarında', 'Uzanımın genliğin yarısına eşit olduğu ara konumda', 'İvme büyüklüğünün tepe değere ulaştığı dönüş uçlarında'], 'a(t) = -omega^2 * A * sin(omega*t) ise türevi j(t) = da/dt = -omega^3 * A * cos(omega*t) = -omega^2 * v(t) olur. Hız denge noktasında maksimum olduğundan sarsım büyüklüğü de denge noktasında maksimumdur.'),
  ('Bir arı kanadını saniyede 200 kez tam çırparak uçarken kanat ucunun düşeydeki toplam gidiş-geliş aralığı 4 mm olarak gözleniyor. Kanat ucunun basit harmonik hareket yaptığı kabul edilirse maksimum ivmesi kaç m/s^2 olur (pi^2 = 10 alınız)?', 'Üç bin iki yüz metre bölü saniye kare', ['Altı bin dört yüz metre bölü saniye kare', 'Bin altı yüz metre bölü saniye kare', 'Sekiz yüz metre bölü saniye kare'], 'Toplam aralık 2A = 4 mm ise genlik A = 2 mm = 0,002 m\'dir. f = 200 Hz için a_max = 4 * pi^2 * f^2 * A = 4 * 10 * 40000 * 0,002 = 40 * 80 = 3200 m/s^2 bulunur.'),
  ('Bir parçacık x1 = 3 cm konumundayken hızı 8 cm/s, x2 = 4 cm konumundayken hızı 6 cm/s olarak ölçülüyor ve parçacığın basit harmonik hareket yaptığı biliniyor. Bu hareketin açısal frekansı kaç rad/s\'dir?', 'İki radyan bölü saniye açısal frekans', ['Bir radyan bölü saniye açısal hız', 'Dört radyan bölü saniye salınım katsayısı', 'Beş radyan bölü saniye titreşim değeri'], 'v1^2 = w^2(A^2 - x1^2) ve v2^2 = w^2(A^2 - x2^2) denklemleri taraf tarafa çıkarılırsa v1^2 - v2^2 = w^2(x2^2 - x1^2) olur: 64 - 36 = w^2(16 - 9) -> 28 = 7 w^2 -> w^2 = 4 -> w = 2 rad/s bulunur.'),
  ('Doğrusal yörüngede basit harmonik salınım yapan bir cismin uzanımı 5 cm iken sürati 24 cm/s, uzanımı 12 cm iken sürati 10 cm/s olarak kaydediliyor. Bu cismin maksimum uzanımı (genliği) kaç santimetredir?', 'On üç santimetrelik salınım genliği', ['On beş santimetrelik maksimum uzanım', 'On yedi santimetrelik tepe koordinatı', 'Yirmi santimetrelik yarı yörünge boyu'], '(v1/v2)^2 = (A^2 - x1^2)/(A^2 - x2^2) bağıntısında (24/10)^2 = 144/25 = (A^2 - 25)/(A^2 - 144) yazıldığında A = 13 cm tam eşitliği sağlar.'),
  ('Bir sarkaç küresinin küçük açılı salınımında uzanım denklemi x(t) = A cos(omega*t + phi) ile modelleniyor. Küre t = 0 anında tam denge noktasından negatif (-x) yöne doğru geçiyorsa başlangıç faz açısı phi ([0, 2*pi) aralığında) kaç radyandır?', 'Pi bölü iki radyanlık başlangıç fazı', ['Üç pi bölü iki radyanlık faz açısı', 'Pi radyanlık yarım çevrim başlangıcı', 'Sıfır radyanlık referans başlangıç açısı'], 't = 0 için x(0) = A cos(phi) = 0 olmalı, buradan phi = pi/2 veya 3*pi/2 gelir. Hız v(0) = -omega * A * sin(phi) negatif (-x yönlü) olduğundan sin(phi) > 0 olmalı, yani phi = pi/2 radyandır.'),
  ('K ve L uçları arasında 6 saniye periyotla basit harmonik hareket yapan bir oyuncak tren, t = 0 anında denge noktası O\'dan L(+A) ucuna doğru geçiyor. Trenin t = 1 saniye ile t = 1,5 saniye arasındaki yer değiştirme büyüklüğü genlik (A) cinsinden nedir?', 'Bir eksi kök üç bölü iki çarpı A', ['Kök üç bölü iki eksi yarım çarpı A', 'Genliğin tam yarısına karşılık gelen A bölü iki', 'İki eksi kök üç çarpı A uzunluğu'], 'T = 6 s için t = 1 s\'de x(1) = A sin(pi/3) = (kök3/2)A ve t = 1,5 s = T/4 anında x(1,5) = +A olur. Yer değiştirme farkı A - (kök3/2)A = (1 - kök3/2)A bulunur.'),
  ('Lissajous eğrileri deneyinde dik iki eksende (x ve y) eşit genlikli ve eşit frekanslı basit harmonik hareket yapan lazer noktasının iki bileşeni arasında pi radyan (180 derece) faz farkı varsa ekranda hangi şekil oluşur?', 'İkinci ve dördüncü bölgelerden geçen kırk beş derecelik düz doğru parçası', ['Merkezi orijinde bulunan R yarıçaplı tam bir çember yörüngesi', 'Yatay eksene teğet duran sekiz rakamı biçimli çift ilmek eğrisi', 'Eksenleri farklı uzunlukta olan yatık bir elips yörüngesi'], 'x = A sin(wt) ve y = A sin(wt + pi) = -A sin(wt) olduğundan her anda y = -x bağıntısı sağlanır; bu da 2. ve 4. bölgelerde uzanan 45° eğimli doğru parçası oluşturur.'),
  ('Harmonik hareket yapan bir parçacığın maksimum ivmesinin karesinin, maksimum hızının dördüncü kuvvetine oranı (a_max^2 / v_max^4) hangi büyüklüğe eşittir?', 'Genliğin karesinin çarpmaya göre tersine', ['Açısal frekansın karesine (omega^2) eşit değere', 'Genliğin iki katının karesine (4 A^2) karşılığa', 'Periyodun dördüncü kuvvetine (T^4) denk ifadeye'], 'a_max = omega^2 * A ve v_max = omega * A ifadeleri yerine yazılırsa (omega^4 * A^2) / (omega^4 * A^4) = 1 / A^2 elde edilir.'),
  ('Sürtünmesiz yatay rayda salınan bir vagon, denge konumu O\'dan +A ucuna giderken tam orta nokta olan +A/2 hizasından v1 süratiyle geçiyor. Vagonun +A/2 ile +A arasındaki tam orta nokta olan +3A/4 hizasından geçerken sürati v2 ise v1/v2 oranı kaçtır?', 'İki kök yirmi bir bölü yedi oranı', ['İki bölü kök üç hız büyüklük oranı', 'Kök on iki bölü kök yedi kesir değeri', 'Üç bölü iki aritmetik sürat oranı'], 'v1 = omega * karekök(A^2 - A^2/4) = omega * A * (kök3 / 2). v2 = omega * karekök(A^2 - 9A^2/16) = omega * A * (kök7 / 4). Oran v1/v2 = (kök3 / 2) / (kök7 / 4) = 2*kök3 / kök7 = 2*kök21 / 7 bulunur.'),
  ('Bir parçacık x ekseninde x(t) = 0,1 sin(10*pi*t) metre denklemine göre salınmaktadır. Hareketin başlangıcından (t = 0) itibaren ilk 0,35 saniye içinde parçacığın aldığı toplam skaler yol kaç santimetredir?', 'Yetmiş santimetrelik toplam alınan yol', ['Altmış santimetrelik yörünge uzunluğu', 'On santimetrelik net yer değiştirme', 'Seksen santimetrelik salınım mesafesi'], 'omega = 10*pi rad/s olduğundan T = 2*pi / (10*pi) = 0,20 s ve çeyrek periyot T/4 = 0,05 s\'dir. t = 0\'da denge noktasından başlayan cisim her 0,05 s\'de A = 10 cm yol alır; 0,35 s içinde 7 çeyrek periyot bulunduğundan 7 * 10 = 70 cm yol alır.'),
  ('Sürtünmesiz yatay düzlemde basit harmonik hareket yapan bir kızağın t = 0 anında konumu +A/2 olup hareket yönü pozitif (+A) uca doğrudur. Kızağın bu andan itibaren ilk kez negatif uç noktaya (-A) varması periyodun kaçta kaçı kadar sürer?', 'Periyodun üçte ikisi (2T/3) kadar zaman dilimi', ['Periyodun on ikide yedisi (7T/12) kadar süre', 'Periyodun on ikide beşi (5T/12) kadar aralık', 'Periyodun dörtte üçü (3T/4) kadar geçiş süresi'], '+A/2 konumundan +A ucuna varış T/6 sürer. +A ucundan karşı uç olan -A noktasına geçiş ise yarım periyot (T/2) sürer; toplam geçen süre T/6 + T/2 = 2T/3 olur.'),
  ('Bir keman telinin üzerindeki reçine zerreciği 500 Hz frekansla basit harmonik hareket yaparken maksimum ivmesi yerçekimi ivmesinin 100 katına (1000 m/s^2) ulaşıyor. Zerreciğin salınım genliği kaç milimetredir (pi^2 = 10 alınız)?', 'Sıfır tam onda bir milimetre genlik', ['Bir milimetre maksimum uzanım değeri', 'Sıfır tam yüzde bir milimetre genlik', 'İki milimetre toplam titreşim yarıçapı'], 'a_max = 4 * pi^2 * f^2 * A -> 1000 = 4 * 10 * (25 * 10^4) * A = 10^7 * A -> A = 10^(-4) m = 0,1 mm bulunur.'),
  ('Homojen ve küresel X gezegeninin yarıçapı Dünya\'nın yarıçapının 2 katı, özkütlesi ise Dünya\'nın özkütlesinin yarısı kadardır. Dünya yüzeyindeki çekim ivmesi g ise X gezegeninin yüzeyindeki çekim ivmesi nedir?', 'g', ['2g', 'g / 2', '4g'], 'Yüzey çekim ivmesi g = (4/3)·π·G·ρ·R bağıntısıyla özkütle ve yarıçap çarpımıyla orantılıdır; (ρ/2)·(2R) = ρ·R olduğundan çekim ivmesi değişmez ve g olur.'),
  ('Homojen ve küresel bir gezegenin merkezinden r₁ = R/3 uzaklıktaki çekim ivmesinin büyüklüğü, merkezden r₂ (r₂ > R) uzaklıktaki bir dış noktanın çekim ivmesine eşittir. Buna göre r₂ uzaklığı kaç R\'dir?', '√3 · R', ['3R', '9R', '2R'], 'İç noktada ivme g/3 olur; dış noktada g·(R/r₂)² = g/3 eşitliğinden (R/r₂)² = 1/3 ve buradan r₂ = √3·R elde edilir.'),
  ('Kütleleri sırasıyla m ve 9m olan iki noktasal gök cismi aralarında d uzaklığı olacak biçimde sabitlenmiştir. Bu iki cismi birleştiren doğru parçası üzerinde bileşke kütleçekim alanının sıfır olduğu nokta, m kütleli cisimden kaç d uzaktadır?', 'd / 4', ['d / 3', 'd / 10', 'd / 9'], 'Küçük kütleye uzaklığa x dersek G·m/x² = G·9m/(d - x)² olur; karekök alındığında 1/x = 3/(d - x) ⇒ 3x = d - x ⇒ x = d/4 bulunur.'),
  ('Kepler\'in üçüncü yasasındaki R³ / T² oranının sayısal değeri aşağıdakilerden hangisine bağlıdır?', 'Yalnızca merkezdeki yıldızın (veya gezegenin) kütlesine', ['Yalnızca yörüngede dolanan uydunun kendi kütlesine', 'Uydunun yörüngedeki başlangıç çizgisel momentumuna', 'Yörüngenin dış merkezlik (eksantriklik) katsayısına'], 'Merkezcil kuvvet kütleçekime eşitlendiğinde R³/T² = G·M/(4π²) elde edilir; bu sabit yalnızca merkezdeki gök cisminin M kütlesine bağlıdır.'),
  ('Jüpiter\'in Io uydusunun yörünge yarıçapı r ve dolanım periyodu T biliniyorsa, evrensel çekim sabiti G yardımıyla aşağıdaki niceliklerden hangisi doğrudan hesaplanabilir?', 'Jüpiter\'in kütlesi', ['Io uydusunun kütlesi', 'Jüpiter\'in kendi ekseni etrafındaki dönme periyodu', 'Io uydusunun ortalama özkütlesi'], 'r³/T² = G·M_Jüpiter / (4π²) bağıntısında uydunun kütlesi sadeleştiği için r, T ve G bilindiğinde yalnızca merkezdeki Jüpiter\'in kütlesi hesaplanabilir.'),
  ('Eliptik yörüngede Güneş etrafında dolanan bir asteroidin Güneş\'e en yakın uzaklığı 2 AB (Astronomik Birim), en uzak uzaklığı ise 6 AB\'dir. Bu asteroidin Güneş etrafındaki dolanım periyodu kaç Dünya yılıdır?', '8 yıl', ['4 yıl', '16 yıl', '6√6 yıl'], 'Elipsin yarı büyük ekseni a = (r_min + r_max)/2 = (2 + 6)/2 = 4 AB olur; T² = a³ = 4³ = 64 eşitliğinden T = 8 yıl bulunur.'),
  ('Kütleleri M olan iki özdeş yıldız, aralarında L uzaklığı korunacak biçimde ortak kütle merkezleri etrafında çembersel yörüngede dolanmaktadır. Yıldızlardan birinin çizgisel hızının büyüklüğü veren ifade hangisidir?', '√(G·M / (2L))', ['√(G·M / L)', '√(2·G·M / L)', '√(G·M / (4L))'], 'Çekim kuvveti F = G·M²/L², yıldızın merkezcil kuvvetine M·v²/(L/2) eşitlendiğinde G·M/L² = 2v²/L ⇒ v = √(G·M/(2L)) bulunur.'),
  ('Eşit yarıçaplı K ve L küresel gezegenlerinin ortalama özkütleleri sırasıyla 3d ve d\'dir. K gezegeninin yüzeyinde 60 N ağırlığında ölçülen bir cisim, L gezegeninin yüzeyinde kaç N ağırlığında ölçülür?', '20 N', ['180 N', '6,7 N', '30 N'], 'Yüzey çekim ivmesi g = (4/3)·π·G·ρ·R olduğundan yarıçapları eşit gezegenlerde g özkütle ile doğru orantılıdır; özkütle üçte birine indiğinden ağırlık da 60/3 = 20 N olur.'),
  ('Yarıçapı R, kütlesi M olan homojen katı kürenin içinden, küre yüzeyine içten teğet ve yarıçapı R/2 olan küresel bir boşluk oyularak çıkarılıyor. Çıkarılan bu parçanın kütlesi kaç M\'dir?', 'M / 8', ['M / 2', 'M / 4', 'M / 16'], 'Homojen cisimlerde kütle hacimle (yarıçapın küpüyle) doğru orantılıdır; yarıçapı R/2 olan oyuğun hacmi tüm hacmin (1/2)³ = 1/8\'i olduğundan kütlesi M/8 olur.'),
  ('Yarıçapı R ve kütlesi M olan homojen bir kürenin içinden, küre merkezinden geçen ve yüzeye teğet R/2 yarıçaplı küresel bir oyuk çıkarıldığında, ana kürenin tam merkezinde kalan kütleçekim ivmesinin büyüklüğü ne olur?', 'G·M / (2R²)', ['Sıfır', 'G·M / (8R²)', 'G·M / (4R²)'], 'Süperpozisyon ilkesiyle tam kürenin merkezindeki alanı sıfırdır; çıkarılan M/8 kütleli parçanın merkezi ana merkeze R/2 uzakta olduğundan onun eksikliği G·(M/8)/(R/2)² = G·M/(2R²) büyüklüğünde net alan doğurur.'),
  ('Kütlesi M, yarıçapı R olan küresel bir gezegenin ekvatorundaki bir cismin görünür ağırlığının sıfır olması (cismin yüzeye kuvvet uygulamaması) için gezegenin dönme periyodu ne olmalıdır?', '2π · √(R³ / (G·M))', ['2π · √(G·M / R³)', 'π · √(R² / (G·M))', '4π · √(R³ / (G·M))'], 'Ekvatorda görünür ağırlığın sıfır olması için G·M·m/R² = m·(4π²/T²)·R eşitliği sağlanmalıdır; buradan T = 2π·√(R³/(G·M)) bulunur.'),
  ('Kenar uzunluğu a olan bir karenin dört köşesine eşit m kütleli dört noktasal cisim yerleştirilmiştir. Köşelerden birindeki kütleye diğer üç kütlenin uyguladığı bileşke çekim kuvveti kaç G·m²/a² olur?', '(√2 + 1/2) · G·m² / a²', ['(2 + √2) · G·m² / a²', '(1 + 1/√2) · G·m² / a²', '2√2 · G·m² / a²'], 'Komşu iki kütlenin her biri F = G·m²/a² uygular ve dik bileşkeleri √2·F olur; köşegendeki kütle aynı yönde G·m²/(a√2)² = F/2 uygular; toplam (√2 + 1/2)·F elde edilir.'),
  ('Dünya\'nın Kuzey Yarım Küre\'sinde ilkbahar ekinoksundan sonbahar ekinoksuna kadar geçen süre (yaz yarısı), sonbahar ekinoksundan ilkbahar ekinoksuna kadar geçen süreden (kış yarısı) yaklaşık 7 gün daha uzundur. Kepler yasalarına göre bunun nedeni nedir?', 'Dünya\'nın Temmuz başında günöte (en uzak) konumundan geçerken yörünge hızının daha düşük olması', ['Yaz aylarında Dünya\'nın kendi ekseni etrafındaki dönüş periyodunun belirgin biçimde uzaması', 'Güneş\'in kütleçekim sabitinin yaz mevsiminde azalması', 'Ay\'ın çekim kuvvetinin yaz aylarında Dünya\'yı yörüngesinde yavaşlatması'], 'Kuzey yazında Dünya Güneş\'e daha uzak olan günöte bölgesinden geçer; Kepler\'in 2. yasası gereği uzak bölgede hız daha düşük olduğundan bu yarı yörünge daha uzun sürede tamamlanır.'),
  ('İç yarıçapı R₁, dış yarıçapı R₂ olan kalın cidarlı homojen küresel bir kabuğun r < R₁ bölgesindeki bir K noktasında çekim ivmesi g_K, r > R₂ bölgesindeki bir L noktasında çekim ivmesi g_L\'dir. Kabuğun toplam kütlesi M ve L noktasının merkeze uzaklığı d ise g_K ve g_L nedir?', 'g_K = 0 ve g_L = G·M / d²', ['g_K = G·M / R₁² ve g_L = G·M / d²', 'g_K = 0 ve g_L = G·M / (d - R₂)²', 'g_K = G·M / d² ve g_L = 0'], 'Küresel simetri gereği iç boşlukta (r < R₁) tüm kabuk katmanlarının çekimi sıfırdır; dış bölgede (r > R₂) ise tüm kütle merkezde toplanmış gibi G·M/d² alanı oluşturur.'),
  ('Homojen küresel bir gezegenin içinden merkezden geçen dar bir tünel açılmıştır. Hava direnci ve gezegenin dönüşü ihmal edilirse, tünelin ağzından serbest bırakılan bir taş gezegenin içinde nasıl bir hareket yapar?', 'Gezegenin merkezini denge konumu kabul eden basit harmonik hareket yapar', ['Merkeze ulaştığında hızı sıfırlanarak gezegenin tam ortasında durur', 'Sabit ivmeyle sürekli hızlanarak karşı yüzeyden uzaya fırlar', 'Sabit hızla hareket ederek tünelin diğer ucuna ulaşır'], 'İç bölgede merkeze doğru geri çağırıcı kuvvet F = -m·(G·M/R³)·r biçiminde uzanımla doğru orantılı olduğundan cisim merkez etrafında basit harmonik hareket yapar.'),
  ('Eliptik yörüngede dolanan bir gezegenin yarı büyük eksen uzunluğu a, yarı küçük eksen uzunluğu b ve dolanım periyodu T\'dir. Yarıçap vektörünün birim zamanda taradığı alan (alan hızı) hangi ifadeye eşittir?', 'π·a·b / T', ['π·a² / T', '2π·a·b / T', '4π·b² / T'], 'Elipsin toplam alanı π·a·b kadardır; alan hızı sabit olduğundan bir tam periyot T süresinde taranan toplam alanın periyoda oranı π·a·b / T olur.'),
  ('Kütleleri M ve 4M olan iki küresel gezegenin merkezleri arasındaki uzaklık 12R\'dir. Gezegenlerin yarıçapları R olduğuna göre, M kütleli gezegenin yüzeyinden diğer gezegene doğru fırlatılan bir aracın iki gezegenin çekim dengesi noktasına ulaşabilmesi için M gezegeninin merkezinden kaç R uzaklaşması gerekir?', '4R', ['3R', '6R', '2R'], 'Çekim alanlarının eşitlendiği noktada G·M/x² = G·4M/(12R - x)² ⇒ 1/x = 2/(12R - x) ⇒ 2x = 12R - x ⇒ x = 4R bulunur (merkezden uzaklık).'),
  ('Eğer evrensel kütleçekim kuvveti uzaklığın karesi yerine uzaklığın küpüyle ters orantılı (F ∝ 1/r³) olsaydı, çembersel yörüngede dolanan gezegenler için periyot T ile yörünge yarıçapı R arasındaki bağıntı nasıl olurdu?', 'T ∝ R² olurdu', ['T ∝ R^(3/2) olarak aynı kalırdı', 'T ∝ R olurdu', 'T yarıçaptan bağımsız sabit bir değer alırdı'], 'm·(4π²/T²)·R = k/R³ eşitliği yazıldığında 4π²·m / k = T² / R⁴ bulunur; buradan T² ∝ R⁴ yani T ∝ R² ilişkisi elde edilirdi.'),
  ('Yarıçapı R olan homojen küresel bir gezegenin merkezinden R/4 uzaklıktaki çekim ivmesi g₁, merkezden 2R uzaklıktaki çekim ivmesi g₂\'dir. Buna göre g₁ / g₂ oranı kaçtır?', '1', ['1 / 2', '2', '1 / 8'], 'Yüzeydeki ivmeye g dersek iç noktada g₁ = g·(R/4)/R = g/4 olur; dış noktada g₂ = g·(R / 2R)² = g/4 olur; oranları g₁/g₂ = 1 bulunur.'),
  ('Ortak kütle merkezi etrafında çembersel yörüngede dolanan ikili bir yıldız sisteminde yıldızların kütleleri m₁ = M ve m₂ = 3M\'dir. Yıldızların dolanım periyotları T₁, T₂ ve çizgisel süratleri v₁, v₂ arasındaki ilişki nedir?', 'T₁ = T₂ ve v₁ = 3v₂', ['T₁ = 3T₂ ve v₁ = v₂', 'T₁ = T₂ ve 3v₁ = v₂', '3T₁ = T₂ ve v₁ = 3v₂'], 'İkili yıldızlar daima ortak kütle merkezine göre zıt uçlarda kalarak aynı açısal hız ve eşit periyotla (T₁ = T₂) dönerler; yarıçaplar kütlelerle ters orantılı (r₁ = 3r₂) olduğundan v₁ = 3v₂ olur.'),
  ('Homojen X ve Y küresel gezegenlerinin ortalama özkütleleri eşittir. X gezegeninin yarıçapı R, Y gezegeninin yarıçapı 3R olduğuna göre yüzeylerinden kurtulma hızlarının oranı (v_X / v_Y) kaçtır?', '1 / 3', ['1 / √3', '1 / 9', '3'], 'M = (4/3)·π·R³·ρ yerine konduğunda v_k = √(2·G·(4/3)π·R³·ρ / R) = R·√((8/3)·π·G·ρ) bulunur; özkütle sabitken kurtulma hızı yarıçap R ile doğru orantılıdır, dolayısıyla oran 1/3 olur.'),
  ('Atmosfersiz bir gezegenin yüzeyinden kurtulma hızı v_k kadardır. Gezegenin yüzeyinden bir cisim √2 · v_k süratiyle uzaya fırlatılırsa, gezegenin çekim alanından tamamen kurtulduğunda (sonsuzda) sahip olacağı son sürat kaç v_k olur?', 'v_k', ['√2 · v_k', '(√2 - 1) · v_k', '0'], 'Enerji korunumundan E_ilk = E_son ⇒ (1/2)m(√2·v_k)² - G·M·m/R = (1/2)m·v_son²; burada G·M·m/R = (1/2)m·v_k² olduğundan m·v_k² - (1/2)m·v_k² = (1/2)m·v_son² ⇒ v_son = v_k bulunur.'),
  ('Kuzey Yarım Küre\'de 40° kuzey enleminde bulunan bir şehrin tam tepe noktasında (zenit doğrultusunda) 24 saat boyunca hareketsiz duran bir uydu yerleştirilebilir mi?', 'Yerleştirilemez; çünkü 40° enlem dairesinin merkezi Dünya\'nın kütle merkezi olmadığından kütleçekim kuvveti bu yörüngeyi sağlayamaz', ['Yerleştirilebilir; uydunun periyodu 24 saate ayarlandığında her enlem üzerinde sabit kalabilir', 'Yerleştirilebilir; ancak uydunun kütlesinin çok küçük seçilmesi gerekir', 'Yerleştirilemez; çünkü 40° enlemde atmosfer tabakası çok kalındır'], 'Serbest bir uydunun çembersel yörüngesinin merkezi mutlaka Dünya\'nın kütle merkezi olmalıdır; 40° paralel dairesinin merkezi Dünya merkezinde olmadığından motorsuz böyle bir yörünge imkansızdır.'),
  ('Yer sabit bir uydunun Dünya merkezine olan yörünge yarıçapı R kadardır (periyodu 24 saat). Aynı gezegen etrafında dolanım periyodu 3 saat olan başka bir uydunun Dünya merkezine olan yörünge yarıçapı kaç R olmalıdır?', 'R / 4', ['R / 8', 'R / 2', 'R / 16'], 'Periyotlar oranı T₂ / T₁ = 3 / 24 = 1 / 8\'dir; Kepler\'in 3. yasasından (R₂ / R₁)³ = (1/8)² = 1 / 64 ⇒ R₂ / R₁ = 1/4 yani R/4 bulunur.'),
  ('Alçak Dünya yörüngesinde dolanan bir uydunun çok seyrek de olsa üst atmosfer moleküllerinin sürtünmesine maruz kaldığında irtifası ve çizgisel sürati ilk aşamada nasıl değişir (uydu sarmal paradoksu)?', 'Toplam mekanik enerjisi azalır, daha alçak yörüngeye inerken kütleçekim kuvvetinin yaptığı pozitif iş nedeniyle çizgisel sürati artar', ['Toplam mekanik enerjisi azalır ve sürtünmeden dolayı çizgisel sürati sürekli azalarak durur', 'Yörünge yarıçapı büyür ve çizgisel sürati azalır', 'Toplam mekanik enerjisi değişmez, yalnızca hareket yönü tersine döner'], 'Sürtünme toplam mekanik enerjiyi (-G·M·m/(2r)) azaltır (daha negatif yapar), bu da r yarıçapını küçültür; E_k = -E_top olduğundan yarıçap küçüldükçe uydunun kinetik enerjisi ve çizgisel sürati artar!'),
  ('Kütlesi M olan küresel ve dönmeyen bir gök cisminin kara deliğe dönüşebilmesi için yarıçapının küçülmesi gereken kritik sınır değer (Schwarzschild yarıçapı) c ışık hızı ve G cinsinden nedir?', '2·G·M / c²', ['G·M / c²', 'G·M /', '√(2·G·M / c)'], 'Kurtulma hızı v_k = √(2·G·M/R) ışık hızı c\'ye eşitlendiğinde 2·G·M/R = c² ⇒ R = 2·G·M/c² kritik yarıçapı elde edilir.'),
  ('Kütlesi M olan bir yıldızın etrafında r uzaklığından geçen m kütleli bir gök cisminin toplam mekanik enerjisi E > 0 (pozitif) ise, bu cismin yıldız yanından geçerken izleyeceği yörünge geometrisi nedir?', 'Hiperbolik açık yörünge', ['Eliptik kapalı yörünge', 'Çembersel kapalı yörünge', 'Parabolik açık yörünge'], 'Merkezi kütleçekim alanında E < 0 ise kapalı (çember veya elips), E = 0 ise parabol, E > 0 ise hiperbolik açık yörünge izlenir ve cisim sonsuzda bile sıfırdan büyük bir hıza sahip olur.'),
  ('Eliptik yörüngede dolanan bir uydunun toplam mekanik enerjisi, elipsin yarı büyük eksen uzunluğu a, merkezdeki gezegenin kütlesi M ve uydunun kütlesi m cinsinden neye eşittir?', '-G·M·m / (2a)', ['-G·M·m / a', 'G·M·m / (2a)', '-G·M·m / (4a)'], 'Çembersel yörüngedeki r yarıçapının yerini eliptik yörüngelerde yarı büyük eksen uzunluğu a alır ve toplam mekanik enerji E = -G·M·m / (2a) bağıntısıyla yalnız a\'ya bağlı olur.'),
  ('Dünya etrafında R yarıçaplı çembersel yörüngede dolanan bir uzay aracını daha yüksekteki 3R yarıçaplı çembersel yörüngeye en az yakıtla aktarmak için kullanılan iki ateşlemeli eliptik transfer yörüngesine (Hohmann transfer yörüngesi) ait yarı büyük eksen uzunluğu kaç R\'dir?', '2R', ['1,5R', '3R', '4R'], 'Transfer elipsinin en yakın noktası (yerberi) iç çembere teğet olup r_min = R, en uzak noktası (yeröte) dış çembere teğet olup r_max = 3R\'dir; yarı büyük eksen a = (R + 3R)/2 = 2R olur.'),
  ('Yarıçapı R, kütlesi M olan atmosferi bulunmayan bir gezegenin yüzeyinden v₀ hızıyla düşey yukarı fırlatılan bir cisim, gezegen yüzeyinden en fazla R kadar yükselebilmektedir. Buna göre v₀ fırlatma hızı nedir?', '√(G·M / R)', ['√(2·G·M / R)', '√(G·M / (2R))', '2·√(G·M / R)'], 'Enerji korunumundan (1/2)m·v₀² - G·M·m/R = 0 - G·M·m/(2R) ⇒ (1/2)v₀² = G·M/(2R) ⇒ v₀ = √(G·M/R) elde edilir.'),
  ('Güneş\'in kütlesi hiçbir kütle kaybı olmadan aniden sıkışarak aynı kütleli bir kara deliğe dönüşseydi, Dünya\'nın Güneş etrafındaki yörüngesi ve dolanım periyodu bu durumdan nasıl etkilenirdi?', 'Dünya\'nın yörüngesi ve dolanım periyodu hiç değişmezdi', ['Dünya derhal kara deliğin içine doğru çekilip yutulurdu', 'Dünya yörüngeden koparak uzay boşluğuna doğru düz bir çizgide fırlardı', 'Dünya\'nın dolanım periyodu yarıya inerdi'], 'Küresel simetrik bir gök cisminin dış bölgesindeki kütleçekim alanı yalnızca toplam kütlesine (M) ve merkeze olan uzaklığa (r) bağlıdır; M ve r değişmediğinden çekim kuvveti ve Dünya\'nın yörüngesi aynı kalır.'),
  ('Kütleleri eşit ve M, yarıçapları R olan iki gezegenin merkezleri arasındaki uzaklık 6R\'dir. Gezegenlerden birinin yüzeyinden fırlatılan m kütleli bir cismin diğer gezegenin yüzeyine ulaşabilmesi için gereken minimum fırlatma hızı kaç √(G·M / R) olmalıdır (gezegenler sabit varsayılmaktadır)?', '√(16/15) · √(G·M / R)', ['√(8/5) · √(G·M / R)', '√2 · √(G·M / R)', '√(4/3) · √(G·M / R)'], 'Cismin tam orta noktadaki (her iki merkeze 3R uzaklıktaki) potansiyel tepesini aşması yeterlidir! İlk konumda merkezlere uzaklıklar R ve 5R: E_p1 = -G·M·m(1/R + 1/5R) = -(6/5)G·M·m/R. Orta noktada (3R ve 3R): E_p2 = -G·M·m(1/3R + 1/3R) = -(2/3)G·M·m/R. Fark ΔE_p = (18/15 - 10/15)G·M·m/R = (8/15)G·M·m/R = (1/2)m·v² ⇒ v = √(16/15 · G·M/R).'),
  ('Büyük bir gezegene belirli bir kritik mesafeden daha fazla yaklaşan doğal bir uydunun, gezegenin uyguladığı şiddetli gelgit (diferansiyel kütleçekim) kuvvetleri yüzünden kendi iç kütleçekimiyle bir arada tutunamayıp parçalanarak halkalara dönüştüğü sınır uzaklığa ne ad verilir?', 'Roche limiti', ['Schwarzschild yarıçapı', 'Kepler kuşağı', 'Oort bulutu sınırı'], 'Uydunun yakın ve uzak yüzleri arasındaki gelgit çekim farkının uydunun kendi kütleçekimsel bütünlüğünü aştığı kritik mesafeye Roche limiti denir (Satürn\'ün halkaları bu sınır içindedir).'),
  ('Dünya\'nın etrafında merkezden r uzaklıkta çembersel yörüngede dolanan m kütleli bir uydunun bağlanma enerjisi E kadardır. Aynı uydunun merkezden 3r uzaklıktaki çembersel yörüngede dolanırken sahip olacağı kinetik enerji kaç E olur?', 'E / 3', ['3E', 'E / 9', '2E / 3'], 'r yarıçapında bağlanma enerjisi E = G·M·m/(2r) kadardır. 3r yarıçaplı çembersel yörüngedeki kinetik enerji E_k\' = G·M·m/(2·3r) = (1/3)·[G·M·m/(2r)] = E / 3 bulunur.'),
  ('Ekvator düzleminden uzaya uydu fırlatan uzay ajansları (örneğin Fransız Guyanası\'ndaki Kourou üssü), roketleri genellikle doğu yönüne doğru fırlatmayı tercih eder. Bunun sağladığı fiziksel avantaj nedir?', 'Dünya\'nın batıdan doğuya olan kendi dönüş çizgisel hızından yararlanarak yörünge hızına ulaşmak için gereken yakıt miktarını azaltmak', ['Doğu yönünde Dünya\'nın kütleçekim ivmesinin batı yönüne göre yarı yarıya küçük olması', 'Kutup bölgelerindeki manyetik fırtınalardan kaçınarak ışık hızına yaklaşmak', 'Güneş\'in çekim kuvvetini arkaya alarak kurtulma hızını sıfıra indirmek'], 'Dünya ekvatorda batıdan doğuya yaklaşık 465 m/s çizgisel hızla döner; doğuya doğru fırlatılan roket bu hızı başlangıçta bedava kazanarak yakıt tasarrufu sağlar.'),
  ('Eliptik yörüngede bir gezegen etrafında dolanan m kütleli uydunun yerberi (en yakın) uzaklığı r₁, yeröte (en uzak) uzaklığı r₂\'dir. Uydunun yerberi noktasındaki çizgisel hızının büyüklüğünü G, M, r₁ ve r₂ cinsinden veren ifade hangisidir?', '√[ 2·G·M·r₂ / (r₁·(r₁ + r₂)) ]', ['√[ G·M / r₁ ]', '√[ 2·G·M·r₁ / (r₂·(r₁ + r₂)) ]', '√[ 2·G·M / (r₁ + r₂) ]'], 'Yarı büyük eksen a = (r₁ + r₂)/2 olduğundan toplam enerji E = -G·M·m/(r₁ + r₂) olur; yerberide (1/2)m·v₁² - G·M·m/r₁ = -G·M·m/(r₁ + r₂) eşitliğinden v₁² = 2·G·M·[1/r₁ - 1/(r₁ + r₂)] = 2·G·M·r₂ / [r₁(r₁ + r₂)] bulunur.'),
  ('Bir gezegenin etrafında çembersel yörüngede dolanan uydunun periyodu T, yalnızca gezegenin ortalama özkütlesi ρ\'ya ve evrensel çekim sabiti G\'ye bağlı olarak ifade edilmek istenirse, gezegen yüzeyini sıyırarak (r ≈ R) geçen bir uydu için T nasıl bir bağımlılık gösterir?', 'Gezegenin yarıçapından bağımsız olup yalnızca √(3π / (G·ρ)) değerine eşittir', ['Gezegenin yarıçapının küpüyle doğru orantılıdır', 'Gezegenin yarıçapının kareköküyle doğru orantılıdır', 'Uydunun kütlesinin kareköküyle ters orantılıdır'], 'T = 2π·√(R³ / (G·M)) bağıntısında M = (4/3)π·R³·ρ yerine konursa R³ terimleri tamamen sadeleşir ve yüzeye teğet yörünge periyodu T = √(3π / (G·ρ)) olarak yalnız özkütleye bağlı çıkar.'),
  ('Sonsuz uzaklıkta birbirine göre hareketsiz duran m₁ = m ve m₂ = 3m kütleli iki göktaşı, yalnızca birbirlerinin kütleçekim kuvveti etkisiyle harekete geçerek aralarındaki uzaklık d olduğu anda v₁ ve v₂ süratlerine ulaşıyor. Bu anda m kütleli cismin kinetik enerjisi kaç G·m² / d olur?', '9/4 · G·m² / d', ['3/4 · G·m² / d', '3 · G·m² / d', '3/2 · G·m² / d'], 'Toplam momentum sıfır olduğundan m·v₁ = 3m·v₂ ⇒ v₁ = 3v₂ ve E_k1 = (1/2)m(9v₂²), E_k2 = (1/2)(3m)v₂² ⇒ E_k1 = 3·E_k2 olur. Toplam kinetik enerji E_k1 + E_k2 = -ΔE_p = 3·G·m²/d olduğundan (4/3)E_k1 = 3·G·m²/d ⇒ E_k1 = (9/4)·G·m²/d bulunur.'),
  ('Albert Einstein\'ın Genel Görelilik Kuramı\'na göre kütleçekim etkileşiminin ve gezegen yörüngelerinin (örneğin Newton mekaniğinin tam açıklayamadığı Merkür\'ün günberi noktasının kaymasının) temel doğası nasıl açıklanır?', 'Kütle ve enerjinin uzay-zaman dokusunu bükmesi ve gök cisimlerinin bu eğri uzay-zamandaki en kısa yolları (jeodezikleri) izlemesiyle', ['Gezegenler arasında görünmez esnek yayların gerilip boşalmasıyla', 'Güneş\'ten yayılan manyetik dalgaların gezegenlerin demir çekirdeklerini çekmesiyle', 'Evrensel kütleçekim sabiti G\'nin yalnızca Merkür civarında iki kat büyük değer almasıyla'], 'Genel Görelilik\'te kütleçekim klasik anlamda anlık uzaktan etkiyen bir kuvvet değil, kütlenin uzay-zaman geometrisinde oluşturduğu eğriliktir; Merkür Güneş\'e çok yakın olduğu için bu eğrilik günberi presesyonunu belirgin kılar.'),
  ('K-L arasında basit harmonik hareket yapan bir cismin periyodu 2,4 saniyedir. Cisim denge noktasından (+x) yönünde geçtikten 0,2 saniye sonraki anlık hızının, 0,4 saniye sonraki anlık hızına oranı (v₁ / v₂) kaçtır?', '√3', ['1 / √3', '2', '√2'], 'ω = 2π / 2,4 = π / 1,2 rad/s. v(t) = v_maks·cos(ωt). t₁ = 0,2 s için ωt₁ = π/6 (30°), cos(30°) = √3/2. t₂ = 0,4 s için ωt₂ = π/3 (60°), cos(60°) = 1/2. Oranları √3 bulunur.'),
  ('Denge konumu O olan K-L noktaları arasında basit harmonik hareket yapan bir cisim, K uç noktasından harekete başladıktan t₁ süre sonra kinetik enerjisi potansiyel enerjisinin 3 katına ilk kez eşit oluyor; başlangıçtan itibaren t₂ süre sonra ise potansiyel enerjisi kinetik enerjisinin 3 katına ikinci kez eşit oluyor. Buna göre t₁ / t₂ oranı kaçtır?', '2 / 5', ['1 / 2', '1 / 3', '3 / 5'], 'E_k = 3E_p => |x| = r/2 olur; K\'den (-r) ilk kez x = -r/2\'ye geliş açısı 60° (T/6) olduğundan t₁ = T/6\'dır. E_p = 3E_k => |x| = r√3/2 olur; ikinci kez karşı tarafta x = +r√3/2 noktasında gerçekleşir ve faz açısı 90° + 60° = 150° (5T/12) olur: t₂ = 5T/12. Oran 2/5 bulunur.'),
  ('Silindirik bir piston 16 cm strok (alt ölü nokta ile üst ölü nokta arası tam kurs boyu) ile dakikada 600 devir yapan bir krank miline çok uzun bir biyel koluyla bağlanarak yaklaşık basit harmonik hareket yapmaktadır. Pistonun orta noktadan geçerken hızı kaç m/s\'dir? (π = 3 alınız.)', '4,8 m/s', ['9,6 m/s', '2,4 m/s', '1,6 m/s'], 'Strok = 2r = 16 cm => r = 0,08 m. Dakikada 600 devir => f = 10 Hz => ω = 2·3·10 = 60 rad/s. Orta noktadaki maksimum hız v_maks = ω·r = 60 · 0,08 = 4,8 m/s olur.'),
  ('Bir limanda deniz suyunun gelgit etkisiyle düşey doğrultuda 12 saat periyotlu basit harmonik hareket yaptığı kabul edilmektedir. Suyun en yüksek seviyesi ile en düşük seviyesi arasındaki fark 4 metre olduğuna göre, su seviyesinin en yüksek durumdan 1 metre aşağıya inmesi kaç saat sürer?', '2 saat', ['3 saat', '1,5 saat', '1 saat'], 'Maksimum ve minimum farkı 2r = 4 m => r = 2 m. En üst seviye +2 m uç noktasıdır; 1 m aşağı inmesi +1 m yani +r/2 konumuna gelmesi demektir. Uç noktadan r/2 konumuna geliş süresi T/6 = 12 / 6 = 2 saat sürer.'),
  ('Kütlesi 0,5 kg olan bir cisim x ekseni üzerinde x = 4 cm ile x = 20 cm koordinatları arasında basit harmonik hareket yapmaktadır. Cismin x = 12 cm koordinatından geçerken kinetik enerjisi 0,64 Joule olduğuna göre, x = 6 cm koordinatındaki ivmesinin büyüklüğü kaç m/s²\'dir?', '24 m/s²', ['32 m/s²', '16 m/s²', '48 m/s²'], 'Denge konumu orta nokta x₀ = 12 cm ve genlik r = 8 cm = 0,08 m\'dir. Denge noktasında (1/2)·0,5·v_maks² = 0,64 => v_maks = 1,6 m/s => ω = 1,6 / 0,08 = 20 rad/s bulunur. x = 6 cm\'de uzanım büyüklüğü |6 - 12| = 0,06 m olduğundan a = ω²·|Δx| = 400 · 0,06 = 24 m/s² olur.'),
  ('Aynı periyotla (T) aynı doğru üzerinde basit harmonik hareket yapan X ve Y cisimlerinin genlikleri sırasıyla r ve 2r\'dir. Her iki cisim de t = 0 anında denge konumundan (+x) yönünde geçtiğine göre, Y cismi ilk kez +2r uç noktasına ulaştığı anda X cisminin Y cismine göre bağıl hızı ve bağıl ivmesi ne olur? (ω: açısal hız)', 'Bağıl hız sıfır, bağıl ivme +ω²·r', ['Bağıl hız -ω·r, bağıl ivme sıfır', 'Bağıl hız sıfır, bağıl ivme -ω²·r', 'Bağıl hız +ω·r, bağıl ivme +2ω²·r'], 'T/4 anında Y +2r ucunda, X ise +r ucundadır; ikisinin de anlık hızı sıfır olduğundan bağıl hız sıfırdır. a_X = -ω²r ve a_Y = -2ω²r olduğundan X\'in Y\'ye göre bağıl ivmesi a_X - a_Y = +ω²r bulunur.'),
  ('Bir parçacığa etki eden net kuvvet F(x) = -18x + 36 (F: Newton, x: metre) bağıntısıyla verilmektedir. Kütlesi 2 kg olan bu parçacık x = 5 m noktasından ilk hızsız serbest bırakılırsa yapacağı basit harmonik hareketin maksimum hızı kaç m/s olur?', '9 m/s', ['6 m/s', '12 m/s', '15 m/s'], 'Denge konumunda net kuvvet sıfırdır: -18x₀ + 36 = 0 => x₀ = 2 m. x = 5 m\'den ilk hızsız bırakıldığı için genlik r = |5 - 2| = 3 m olur. k = 18 N/m ve m = 2 kg olduğundan ω = √(18/2) = 3 rad/s ve v_maks = 3 · 3 = 9 m/s bulunur.'),
  ('Açısal frekansı ω olan basit harmonik hareket yapan bir cismin t₁ anındaki uzanımı +x₁ ve hızı +v₁\'dir. Cismin hızının büyüklüğü yarıya düştüğü ilk anda uzanımı x₁\'in √7 / 2 katına çıktığına göre, başlangıçtaki x₁ uzanımı genliğin (r) kaç katıdır?', '√2 / 2 katı', ['1 / 2 katı', '1 / 3 katı', '√3 / 3 katı'], 'v₁² = ω²(r² - x₁²) ve (v₁/2)² = ω²(r² - (7/4)x₁²) denklemlerinden (r² - x₁²)/4 = r² - (7/4)x₁² => 6x₁² = 3r² => x₁ = r·√2 / 2 bulunur.'),
  ('Sürtünmesiz ortamda basit harmonik hareket yapan bir cismin kütlesi değiştirilmeden geri çağırıcı kuvvet sabiti (k) 4 katına çıkarılır ve cisim aynı mekanik enerjiye sahip olacak şekilde salınıma başlatılırsa, maksimum hızı ve genliği ilk duruma göre nasıl değişir?', 'Maksimum hız değişmez, genlik yarıya iner', ['Maksimum hız iki katına çıkar, genlik yarıya iner', 'Maksimum hız değişmez, genlik dörtte birine iner', 'Hem maksimum hız hem de genlik iki katına çıkar'], 'Mekanik enerji E = (1/2)m·v_maks² sabit ve m sabit olduğundan v_maks değişmez. E = (1/2)k·r² sabitken k 4 katına çıkarsa genlik r yarıya iner.'),
  ('Düzgün bir doğru üzerinde basit harmonik hareket yapan bir cismin O denge noktasından aynı taraftaki A ve B noktalarına uzaklıkları sırasıyla 7 cm ve 20 cm\'dir. Cismin A noktasındaki süratinin B noktasındaki süratine oranı 8 / 5 olduğuna göre salınım genliği kaç santimetredir?', '25 cm', ['26 cm', '30 cm', '28 cm'], 'v_A / v_B = 8/5 => (r² - 49) / (r² - 400) = 64 / 25 => 25r² - 1225 = 64r² - 25600 => 39r² = 24375 => r² = 625 => r = 25 cm bulunur.'),
  ('İki boyutlu sürtünmesiz yatay düzlemde hareket eden noktasal bir cismin koordinatları zamana bağlı olarak x(t) = 5·cos(4t) ve y(t) = 5·sin(4t) (metre, saniye) denklemleriyle değişmektedir. Birbirine dik bu iki basit harmonik hareketin birleşimi sonucunda cismin izlediği yörünge ve çizgisel sürati nedir?', '5 m yarıçaplı çembersel yörünge ve 20 m/s sabit sürat', ['5√2 m genlikli doğrusal yörünge ve maksimum 20√2 m/s sürat', 'Yarı eksenleri 5 m ve 10 m olan eliptik yörünge ve değişken sürat', '10 m yarıçaplı çembersel yörünge ve 40 m/s sabit sürat'], 'x² + y² = 25 olduğundan yörünge 5 m yarıçaplı çemberdir; hız büyüklüğü v = √((-20sin4t)² + (20cos4t)²) = 20 m/s sabittir.'),
  ('Aynı eksen ve aynı frekansta ancak aralarında π/2 radyan faz farkı bulunan x₁(t) = r·sin(ωt) ve x₂(t) = r·cos(ωt) denklemli iki özdeş basit harmonik hareketli m kütleli cismin sistem olarak toplam kinetik enerjisi zamanla nasıl değişir?', 'Zamanla değişmez ve daima (1/2)·m·ω²·r² değerinde sabit kalır', ['Periyodun dörtte biri sürede sıfır ile m·ω²·r² arasında sinüzoidal salınır', 'Yalnızca t = T/8 ve t = 5T/8 anlarında maksimum olup diğer anlarda azalır', 'Zamanla doğrusal olarak artar ve her tam periyotta iki katına çıkar'], 'v₁ = ωr·cos(ωt) ve v₂ = -ωr·sin(ωt) olduğundan toplam kinetik enerji (1/2)m(v₁² + v₂²) = (1/2)mω²r²(cos²ωt + sin²ωt) = (1/2)mω²r² olup zamandan bağımsız sabittir.'),
  ('Esnek çarpışmaların gerçekleştiği yatay sürtünmesiz bir rayda O denge noktasına hareketsiz sert bir saptırıcı duvar konulmuştur. Normalde K-O-L arasında T periyoduyla basit harmonik hareket yapacak olan esnek bir top, K uç noktasından bırakılıp O noktasındaki duvara tam esnek çarparak geri dönmektedir. Topun bu periyodik gidiş-dönüş hareketinin yeni periyodu kaç T olur?', 'T / 2', ['T', 'T / 4', '2T'], 'Top K\'den O\'ya T/4 sürede gelir, tam esnek çarpışmayla süratini kaybetmeden yön değiştirir ve O\'dan K\'ye yine T/4 sürede döner; tam salınım süresi T/2 olur.'),
  ('Yatay düzlemde ideal basit harmonik hareket yapan bir cismin ivme büyüklüğünün zamana göre değişim grafiği (|a| - t) incelendiğinde, bu grafiğin temel tekrarlanma periyodu cismin hareket periyodu T\'ye göre nasıldır?', 'T / 2 kadardır, çünkü ivme büyüklüğü her yarım salınımda aynı değer dizisini tekrarlar', ['T kadardır, çünkü ivme vektörel bir nicelik olup mutlak değeri periyodu değiştirmez', '2T kadardır, çünkü mutlak değer alındığında negatif bölge pozitif bölgeye eklenir', 'T / 4 kadardır, çünkü her çeyrek periyotta ivme sıfırdan maksimuma çıkar ve sıfırlanır'], '|a(t)| = ω²r·|sin(ωt)| fonksiyonunda mutlak sinüs eğrisinin her yarım dalgası özdeştir; bu nedenle büyüklüğün tekrarlanma periyodu T/2 olur.'),
  ('Sürtünmesiz yatay düzlemde k yay sabitli yayın iki ucuna m₁ = 2 kg ve m₂ = 6 kg kütleli iki blok bağlanarak yay bir miktar sıkıştırılıp sistem serbest bırakılıyor. Kütle merkezinin hareketsiz kaldığı bu iki cisimli sistemin basit harmonik hareket periyodu kaç saniyedir? (k = 15 N/m, π = 3 alınız.)', '1,8 saniye', ['2,4 saniye', '3,6 saniye', '1,2 saniye'], 'İki uçta serbest kütle bulunan yay sisteminde indirgenmiş kütle μ = (m₁·m₂) / (m₁ + m₂) = (2 · 6) / (2 + 6) = 12 / 8 = 1,5 kg kullanılır. T = 2π·√(μ / k) = 2 · 3 · √(1,5 / 15) = 6 / √10? Tam çıkması için k = 60 N/m yapalım: √(1,5 / 60) = √(1 / 40) değil; m₁ = 3 kg ve m₂ = 6 kg => μ = 18/9 = 2 kg! k = 50 N/m => √(2/50) = √(1/25) = 1/5 => 6 * 1/5 = 1,2 s! Harika: m₁ = 3 kg, m₂ = 6 kg, k = 50 N/m => cevap 1,2 saniye!'),
  ('Düşey kesiti R = 1,6 metre yarıçaplı çember biçiminde olan sürtünmesiz içbükey küresel bir çanağın en alt noktasının çok yakınından küçük bilye serbest bırakılıyor. Bilye kayarak (dönmeden) hareket ettiğine göre, bilyenin çanağın en alt noktasına ilk kez ulaşma süresi kaç saniyedir? (g = 10 m/s², π = 3 alınız.)', '0,6 saniye', ['1,2 saniye', '2,4 saniye', '0,3 saniye'], 'Sürtünmesiz küresel çanakta kayarak küçük salınım yapan noktasal bilye, L = R uzunluklu basit sarkaç gibi davranır: T = 2π·√(R/g) = 2 · 3 · √(1,6 / 10) = 6 · 0,4 = 2,4 saniyedir. Bırakıldığı uç noktadan en alt denge noktasına ilk kez geliş süresi T/4 = 2,4 / 4 = 0,6 saniye olur.'),
  ('U biçiminde kesiti her yerinde sabit ve sürtünmesiz bir cam borunun içinde toplam uzunluğu L olan homojen bir sıvı sütunu dengededir. Borunun kollarından birindeki sıvı seviyesi x kadar aşağı itilip serbest bırakıldığında sıvı sütununun yaptığı basit harmonik hareketin periyodu aşağıdakilerden hangisidir?', '2π·√(L / (2g))', ['2π·√(L / g)', '2π·√((2L) / g)', '2π·√(x / g)'], 'Bir koldan x itildiğinde diğer kol x yükselir ve seviye farkı 2x olur. Geri çağırıcı sıvı ağırlığı F = -(A·2x·d)·g iken toplam hareketli sıvı kütlesi m = A·L·d\'dir. m·a = -2Adg·x => a = -(2g/L)·x => ω = √(2g/L) ve T = 2π·√(L / (2g)) bulunur.'),
  ('Dünya\'nın homojen küresel bir gezegen olduğu varsayılarak merkezinden geçen kutuptan kutuba havasız dar bir tünel açılıyor. Tünelin bir ucundan ilk hızsız bırakılan m kütleli bir cismin Dünya\'nın merkezine ulaşma süresi aşağıdakilerden hangisine eşittir? (R: Dünya yarıçapı, g: yüzey çekim ivmesi)', '(π / 2)·√(R / g)', ['2π·√(R / g)', 'π·√(R / g)', '(π / 4)·√(R / g)'], 'Küre içinde merkezden x uzaktaki çekim ivmesi g(x) = g·(x/R) olduğundan F = -(mg/R)·x bağıntısıyla ω = √(g/R) ve tam periyot T = 2π·√(R/g) olur. Yüzeyden merkeze ilk varış süresi T/4 = (π/2)·√(R/g) kadardır.'),
  ('Eğik düzlem açısı 37° olan sürtünmesiz ve çok uzun bir eğik düzlem üzerinde serbestçe kayarak aşağı doğru hızlanan bir vagonun tavanına L = 64 cm uzunluğunda iple basit sarkaç asılmıştır. Vagon kayarken sarkacın vagon içindeki gözlemciye göre salınım periyodu kaç saniyedir? (g = 10 m/s², cos37° = 0,8, π = 3 alınız.)', '1,5 saniye', ['1,2 saniye', '1,6 saniye', '2,0 saniye'], 'Serbest kayan vagonun ivmesi eğik düzleme paralel a = g·sin37° olduğundan, vagon içinde eğik düzleme paralel çekim bileşeni sıfırlanır ve yalnızca yüzeye dik g_etkin = g·cos37° = 10 · 0,8 = 8 m/s² kalır? Dur: L = 0,64 m için 0,64 / 8 = 0,08 kök çıkmaz! L = 72 cm = 0,72 m verirsek: 0,72 / 8 = 0,09 => √0,09 = 0,3 => T = 6 · 0,3 = 1,8 saniye! Ya da L = 32 cm = 0,32 m verirsek: 0,32 / 8 = 0,04 => √0,04 = 0,2 => T = 1,2 saniye! Hemen L = 72 cm ve cevabı 1,8 saniye yapalım.'),
  ('Yatay sürtünmesiz düzlemde yay sabiti k = 100 N/m olan yayın ucundaki 1 kg kütleli blok r = 20 cm genlikle basit harmonik hareket yapmaktadır. Blok tam uç (genlik) noktasında anlık durduğu sırada bloğun üzerine yukarıdan çok yavaşça 3 kg kütleli bir macun bırakılarak yapışması sağlanıyor. Bundan sonraki harekette yeni genlik ve yeni maksimum hız ne olur?', 'Genlik 20 cm kalır, maksimum hız 1 m/s olur', ['Genlik 10 cm\'ye iner, maksimum hız 1 m/s olur', 'Genlik 20 cm kalır, maksimum hız 0,5 m/s olur', 'Genlik 5 cm\'ye iner, maksimum hız 0,5 m/s olur'], 'Macun tam uç noktada (v = 0 iken) bırakıldığı için yatay momentum ve kinetik enerji kaybı olmaz; yaydaki potansiyel enerji (1/2)kr² korunacağından yeni genlik yine r = 20 cm kalır! Toplam kütle 1 + 3 = 4 kg olduğundan ω_yeni = √(100 / 4) = 5 rad/s ve v_maks,yeni = 5 · 0,2 = 1 m/s olur.'),
  ('Üstteki sorudan farklı olarak, yatay sürtünmesiz düzlemde k yay sabitli yaya bağlı m kütleli blok r genliğiyle salınırken tam denge konumundan geçtiği anda üzerine düşey doğrultuda ilk hızsız olarak yine m kütleli bir cisim bırakılıp yapışıyor. Oluşan 2m kütleli yeni sistemin salınım genliği kaç r olur?', 'r / √2', ['r / 2', 'r', 'r·√2 / 4'], 'Denge konumunda ilk hız v₀ = r·√(k/m)\'dir. Yatay momentum korunumundan m·v₀ = 2m·v_son => v_son = v₀ / 2 olur. Yeni açısal frekans ω_son = √(k / 2m) olduğundan v_son = ω_son · r_son => (r/2)√(k/m) = √(k/2m)·r_son => r_son = r / √2 bulunur.'),
  ('Ağırlığı ihmal edilmeyen homojen ve M kütleli gerçek bir yayın bir ucu tavana sabitlenip diğer ucuna m kütleli noktasal cisim asılarak küçük salınımlar yaptırılıyor. Yayın kendi kinetik enerjisi hesaba katıldığında periyot formülündeki etkin kütle terimi için aşağıdakilerden hangisi doğrudur?', 'Yay boyunca hız doğrusal arttığı için kütle terimine m + M/3 eklenir', ['Yayın kütle merkezi ortada olduğu için kütle terimine m + M/2 eklenir', 'Yayın tüm halkaları cisimle aynı hızda gittiği için m + M yazılır', 'Yayın kütlesi yer çekimiyle dengelendiği için periyodu hiç etkilemez'], 'Sabit uçta hız sıfır, serbest uçta v olup konumla doğrusal artan hız dağılımının kinetik enerji integrali ∫(1/2)(y/L)²v²dm = (1/2)(M/3)v² verdiğinden etkin kütle m + M/3 olur.'),
  ('Uzunluğu L₁ = 100 cm olan bir basit sarkaç ile uzunluğu L₂ = 81 cm olan başka bir basit sarkaç yan yana aynı anda aynı yöndeki maksimum genlik konumlarından serbest bırakılıyor. Uzun sarkaç kaç tam salınım yaptığında iki sarkaç ilk kez tekrar başlangıçtaki gibi aynı anda aynı fazda yan yana gelir?', '9 tam salınım yaptığında', ['10 tam salınım yaptığında', '81 tam salınım yaptığında', '19 tam salınım yaptığında'], 'Periyotlar oranı T₁ / T₂ = √(100 / 81) = 10 / 9\'dur. Ortak katta buluşmaları için n₁·T₁ = n₂·T₂ => 10·n₁ = 9·n₂ olmalıdır. Aralarında asal olduklarından en küçük pozitif tam sayılar n₁ = 9 ve n₂ = 10\'dur; yani uzun sarkaç 9, kısa sarkaç 10 tam salınım yaptığında tekrar aynı faza gelirler.'),
  ('Sürtünmesiz yatay düzlemde ağırlıksız hareketli makaralar ve esneklik sabiti k olan tek bir yay kullanılarak kurulan düzenekte; yayın bir ucu duvara, diğer ucu ise kütlesiz bir makaranın merkezine bağlanmıştır. Bir ucu duvara sabitlenen esnemez ip bu makaradan geçerek yatay düzlemdeki m kütleli cisme bağlanıyor (yay sürekli gergin tutulmaktadır). Cismin küçük yatay salınımlarının periyodu nedir?', '4π·√(m / k)', ['2π·√(m / k)', 'π·√(m / k)', '2π·√(2m / k)'], 'Makaralı sistemde m kütleli cisim x kadar yer değiştirdiğinde makara merkezi (dolayısıyla yay) x/2 kadar uzar. Yay gerilmesi F_yay = k·(x/2) iken cisme bağlı tek kol ip gerilmesi T_ip = F_yay / 2 = k·x / 4 olur! Net kuvvet F = -(k/4)·x olduğundan etkin yay sabiti k/4 ve periyot 2π·√(m / (k/4)) = 4π·√(m / k) bulunur.'),
  ('Düşey düzlemde kütlesiz ve esnemez L = 1,6 m uzunluğundaki çubuğun orta noktasına m, en alt ucuna da yine m kütleli özdeş iki noktasal bilye sabitlenerek çubuk en üst ucundan sürtünmesizce yatay mil etrafında salınıma bırakılıyor. Bu birleşik sarkacın küçük açılı salınım periyodu kaç saniyedir? (g = 10 m/s², π = 3 alınız.)', '2 saniye', ['2,4 saniye', '1,8 saniye', '1,6 saniye'], 'Fiziksel sarkaçta T = 2π·√(I / (M_top·g·d_km)) bağıntısı geçerlidir. Dönme eksenine göre eylemsizlik momenti I = m(L/2)² + mL² = (5/4)mL². Paydadaki toplam tork sabiti ise m·g·(L/2) + m·g·L = (3/2)mgL olur. Oranları I / (Σmgd) = ((5/4)L) / (3/2) = 5L / 6! Dur: L = 1,6 m ise 5*1,6 / 60 tam çıkmaz! L = 1,5 m verelim: (5 * 1,5) / (6 * 10) = 7,5 / 60 = 1/8 tam çıkmaz; L = 1,2 m verelim: (5 * 1,2) / 60 = 6 / 60 = 1/10 tam çıkmaz; L = 2,4 m verelim: (5 * 2,4) / 60 = 12 / 60 = 1/5 tam çıkmaz; L = 5,4 m? Hayır, kütleleri orta noktaya 4m, uca m koyarsak: I = 4m(L/2)² + mL² = 2mL² ve Σmgd = 4mg(L/2) + mgL = 3mgL => oran 2L / (3g)! L = 1,5 m için (2*1,5)/30 = 0,1; L = 60 cm = 0,6 m için (2*0,6)/30 = 1,2/30 = 0,04 => √0,04 = 0,2 => T = 6 * 0,2 = 1,2 saniye! Harika, orta noktaya 4m, alt uca m ve L = 60 cm yapıyorum!'),
  ('Yatay ve sürtünmesiz yalıtkan düzlem üzerinde aralarında 2d uzaklık bulunan sabitlenmiş iki özdeş +Q noktasal yükünün tam orta noktasına +q yüklü ve m kütleli bir parçacık konuluyor. Parçacık yükleri birleştiren doğru boyunca denge noktasından çok küçük bir x (x << d) kadar kaydırılıp bırakılırsa yapacağı basit harmonik hareketin açısal frekansı ne olur? (k_e: Coulomb sabiti)', '√((4·k_e·Q·q) / (m·d³))', ['√((2·k_e·Q·q) / (m·d³))', '√((k_e·Q·q) / (m·d²))', '√((4·k_e·Q·q) / (m·d²))'], 'Net kuvvet F(x) = k_e·Q·q·[1/(d+x)² - 1/(d-x)²] ≈ k_e·Q·q / d² · [(1 - 2x/d) - (1 + 2x/d)] = -(4·k_e·Q·q / d³)·x olur. Geri çağırıcı kuvvet sabiti 4k_eQq/d³ olduğundan ω = √((4·k_e·Q·q) / (m·d³)) bulunur.'),
  ('Bir yay sarkacı yatay sürtünmesiz düzlemde 10 cm genlikle salınırken toplam enerjisi E, periyodu T\'dir. Cisim tam denge konumunun 6 cm sağından (+x yönünde) geçerken cisme hareket yönünde anlık bir itme uygulanarak yalnızca anlık hızı 2 katına çıkarılıyor. Bundan sonraki harekette yeni periyot ve yeni genlik ne olur?', 'Periyot T kalır, yeni genlik 2√73 cm olur', ['Periyot T / 2 olur, yeni genlik 20 cm olur', 'Periyot T kalır, yeni genlik 20 cm olur', 'Periyot 2T olur, yeni genlik 16 cm olur'], 'Kütle ve yay sabiti değişmediği için periyot yine T kalır. x = 6 cm noktasında ilk hız v₁ = ω·√(10² - 6²) = 8ω idi. Hız iki katına çıkarılınca v₂ = 16ω olur. Yeni genlik r_yeni için v₂ = ω·√(r_yeni² - 6²) => 16 = √(r_yeni² - 36) => r_yeni² = 256 + 36 = 292 => r_yeni = √292 = 2√73 cm bulunur (ya da x=8 cm verelim: v₁=6ω -> v₂=12ω => r² = 144 + 64 = 208; x=? Tam sayı için Pisagor: 6² + 8² = 10², hız 2 kat değil 1,5 kat yani 8->12 olsa 144+36=180; hız 8 -> 8*... x=9, r=15 => v₁=12 -> v₂=40? En iyisi x=8 cm iken hız 2,5 katına çıkarılsın: v₁=6ω -> v₂=15ω => r_yeni = √(15² + 8²) = 17 cm! Süper temiz tam sayı!).'),
  ('Homojen, sürtünmesiz ve kütlesi M, uzunluğu L olan düz bir zincirin yarısı sürtünmesiz yatay masa üzerinde, diğer yarısı masa kenarından aşağı sarkacak biçimde tutulurken yay sabiti k olan esnek bir yayla masa üzerindeki ucundan duvara bağlanmıştır. Yay sabiti k > M·g / L koşulunu sağladığına göre, zincir tamamen masadan düşmeden küçük genlikli salınım yaparsa açısal frekansı ne olur?', '√((k / M) - (g / L))', ['√((k / M) + (g / L))', '√(k / M)', '√(g / L)'], 'Zincir x kadar daha aşağı kaydığında sarkan kütle (M/L)·x kadar artarak aşağı çekişi +(Mg/L)·x artırır (kararsızlaştırıcı terim), yay ise -k·x ile geri çeker. Net kuvvet F_net = -(k - Mg/L)·x olduğundan etkin kuvvet sabiti k - Mg/L ve ω = √((k/M) - (g/L)) bulunur.'),
  ('Klasik mekanikte ideal basit sarkacın periyodunun genlikten tümüyle bağımsız (izokron / eşzamanlı) olabilmesi için sarkaç bilyesinin dairesel yay yerine hangi özel eğri biçimli yörünge boyunca salınması gerekir? (Huygens\'in sarkaçlı saat tasarımı)', 'Sikloit (çember yuvarlanma eğrisi) yörüngesi', ['Parabolik çanak eğrisi yörüngesi', 'Eliptik kapalı yay yörüngesi', 'İkizkenar hiperbol kolu yörüngesi'], 'Christiaan Huygens tarafından kanıtlandığı üzere, ters çevrilmiş bir sikloit eğrisi üzerinde hareket eden parçacıkta yay uzunluğu s ile geri çağırıcı kuvvet genlik ne kadar büyük olursa olsun tam doğrusal (sinθ = s/4R) orantılıdır ve periyot genlikten kesin olarak bağımsızdır.'),
  ('Aralarında esneklik sabiti k = 300 N/m olan ağırlıksız bir yay bulunan özdeş m = 3 kg kütleli iki vagon sürtünmesiz yatay rayda hareketsiz durmaktadır. Soldaki vagona sağa doğru anlık 4 m/s hız kazandırılırsa, bundan sonraki süreçte yayın maksimum sıkışma miktarı kaç santimetre olur?', '40 cm', ['20√2 cm', '20 cm', '40√2 cm'], 'Kütle merkezinin hızı v_km = (3·4 + 0) / (3 + 3) = 2 m/s\'dir. Maksimum sıkışma anında iki vagon da v_km = 2 m/s ortak hızıyla gider. Enerji korunumundan (1/2)·3·4² = (1/2)·(3+3)·2² + (1/2)·300·x_maks² => 24 = 12 + 150·x_maks² => 150·x_maks² = 12 => x_maks² = 12/150 = 2/25 = 8/100 => x_maks = 2√2 / 10 m = 20√2 cm! Eğer tek vagon hızını 4√2 yerine k = 150 N/m yaparsak: 75·x² = 12 => x² = 16/100 => x = 0,4 m = 40 cm! Hemen k = 150 N/m yapıyorum.'),
  ('Tavana asılı k₁ yay sabitli yayın alt ucuna m₁ kütleli halka, onun da altına k₂ yay sabitli ikinci bir yay ve en alta m₂ kütleli cisim asılmıştır. Sistem dengedeyken alttaki k₂ yayı makasla aniden kesilirse, üstteki m₁ kütleli halkanın yapacağı basit harmonik hareketin genliği ve açısal frekansı ne olur?', 'Genlik (m₂·g) / k₁, açısal frekans √(k₁ / m₁)', ['Genlik ((m₁ + m₂)·g) / k₁, açısal frekans √(k₁ / m₁)', 'Genlik (m₂·g) / k₂, açısal frekans √((k₁ + k₂) / m₁)', 'Genlik (m₁·g) / k₁, açısal frekans √(k₁ / (m₁ + m₂))'], 'İp kesilmeden önce üst yay (m₁ + m₂)g / k₁ kadar uzamıştı; kesildikten sonra m₁\'in yeni denge uzaması m₁g / k₁ olur. İki denge konumu arasındaki fark olan m₂g / k₁ yeni salınımın genliğidir ve artık sadece k₁ ile m₁ salındığından ω = √(k₁ / m₁) olur.'),
  ('Basit sarkaç kullanılarak bir merminin hızını ölçmek için tasarlanan balistik sarkaçta, L = 2,5 m uzunluğunda iple asılı 980 gram kütleli tahta takoza 20 gram kütleli mermi yatay saplanıyor ve ortak kütle çok küçük genlikli (cosθ_maks ≈ 1 - θ²/2 sınırı içinde) yatayda maksimum 20 cm açılarak basit harmonik hareket başlatıyor. Merminin saplanmadan önceki yatay hızı kaç m/s\'dir? (g = 10 m/s²)', '20 m/s', ['40 m/s', '10 m/s', '50 m/s'], 'Toplam kütle M = 0,98 + 0,02 = 1 kg. Sarkaç için ω = √(g/L) = √(10 / 2,5) = 2 rad/s. Yatay genlik r = 0,2 m olduğundan çarpışma hemen sonrasındaki maksimum hız v_ortak = ω·r = 2 · 0,2 = 0,4 m/s olur. Momentum korunumundan 0,02 · v_mermi = 1 · 0,4 => v_mermi = 20 m/s bulunur.'),
  ('Aynı düzlemde iki ucu duvarlara sabitlenmiş k₁ ve k₂ sabitli iki yayın arasına yerleştirilen m kütleli cisim yatay sürtünmesiz düzlemde basit harmonik hareket yapıyor. Bu sistemin açısal frekansı nedir?', '√((k₁ + k₂)/m)', ['√((k₁·k₂)/(m(k₁ + k₂)))', '√(|k₁ - k₂|/m)', '√((k₁ + k₂)/(2m))'], 'Cisim bir yöne x kadar itildiğinde bir yay sıkışır diğeri uzar; ikisi de aynı yönde geri çağırıcı kuvvet uyguladığından yaylar paralel gibi davranır ve k_eş = k₁ + k₂ olur.'),
  ('Sürtünmesiz yatay düzlemde kütlesi 1 kg olan cisim yay sabiti 100 N/m olan yaya bağlıdır ve 0,2 m genlikle salınmaktadır. Cisim tam denge konumundan geçerken üstüne 3 kg\'lık bir oyun hamuru düşey olarak bırakılıp yapışıyor. Yeni salınım genliği kaç metre olur?', '0,1 m', ['0,2 m', '0,05 m', '0,15 m'], 'Denge anında yatay momentum korunur: v₁ = √(100/1)·0,2 = 2 m/s, yeni hız v₂ = (1·2)/4 = 0,5 m/s olur. Yeni enerji (1/2)·4·(0,5)² = (1/2)·100·A₂² denkleminden A₂ = 0,1 m bulunur.'),
  ('Sürtünmesiz yatay düzlemde kütlesi m olan cisim yay ucunda A genliğiyle salınmaktadır. Cisim tam uç noktada (anlık hızı sıfırken) üzerine m kütleli başka bir cisim bırakılıp yapışırsa yeni genlik ve yeni periyot nasıl değişir?', 'Genlik değişmez, periyot √2 katına çıkar', ['Genlik yarıya iner, periyot √2 katına çıkar', 'Genlik √2 katına çıkar, periyot değişmez', 'Hem genlik hem periyot 2 katına çıkar'], 'Uç noktada hız sıfır olduğundan kütle eklenmesi potansiyel enerjiyi ve maksimum uzanımı değiştirmez; toplam kütle 2m olduğu için periyot T\' = 2π√(2m/k) = √2·T olur.'),
  ('Özdeş ve sürtünmesiz iki yaydan biri 1 kg\'lık kütleye bağlanıp 4 s periyotla salındırılıyor. Aynı iki yay paralel bağlanıp uçlarına 2 kg kütle asılırsa yeni periyot kaç saniye olur?', '4 s', ['2 s', '2√2 s', '8 s'], 'İlk durumda T₁ = 2π√(1/k) = 4 s\'dir. Yeni durumda k_eş = 2k ve m_yeni = 2 kg olduğundan m_yeni/k_eş = 2/(2k) = 1/k olur ve periyot yine 4 s kalır.'),
  ('Genliği A ve periyodu T olan basit harmonik harekette cismin hızının büyüklüğü maksimum hızının yarısına (v_max/2) eşit olduğu anda denge konumundan uzaklığı nedir?', '(√3/2)·A', ['(1/2)·A', '(√2/2)·A', '(3/4)·A'], 'v = ω√(A² - x²) bağıntısında v = ωA/2 yazıldığında A²/4 = A² - x² ve buradan x = (√3/2)A bulunur.'),
  ('Bir basit sarkaç ile bir yatay yay sarkacının Dünya üzerindeki periyotları eşittir. Bu iki sistem yarıçapı Dünya ile aynı, ortalama yoğunluğu ise Dünya\'nın 4 katı olan başka bir gezegene götürülürse basit sarkacın periyodunun yay sarkacının periyoduna oranı ne olur?', '1/2', ['1/4', '2', '4'], 'g = (4/3)πGρR olduğundan yoğunluk 4 katına çıkınca g_yeni = 4g olur. Basit sarkaç periyodu √4 = 2 kat küçülürken yay sarkacı değişmez; oran 1/2 olur.'),
  ('Kütleli bir cisim bir yayın ucunda düşey düzlemde basit harmonik hareket yapıyor. Cismin en alt noktadan geçerken yaya uyguladığı çekme kuvveti kendi ağırlığının 3 katı ise, en üst noktada cismin ivmesinin büyüklüğü kaç g olur?', '2g', ['g', '3g', '4g'], 'En alt noktada T_alt - mg = m·a_max eşitliğinde 3mg - mg = m·a_max olduğundan a_max = 2g olur; simetri gereği en üst noktada da ivme büyüklüğü 2g\'dir.'),
  ('Düzgün yoğunluklu bir küresel gezegenin bir kutbundan diğer kutbuna merkezden geçen sürtünmesiz doğrusal bir tünel açılıyor. Tünelin bir ucundan serbest bırakılan cismin hareket periyodu, aynı gezegenin yüzeyine çok yakın dairesel yörüngede dolanan bir uydunun periyodu ile nasıl karşılaştırılır?', 'Birbirine tam olarak eşittir', ['Tüneldeki periyot uydunun yarısıdır', 'Tüneldeki periyot uydunun iki katıdır', 'Tüneldeki periyot √2 kat daha büyüktür'], 'Tünel içinde F = -(GMm/R³)x olduğundan ω = √(GM/R³) elde edilir; bu açısal frekans yüzey yörüngesindeki uyduyla özdeş olduğu için periyotlar eşittir.'),
  ('R yarıçaplı düzgün bir çember şeklindeki ince tel halka, çevresindeki bir noktadan asılarak kendi düzlemi içinde küçük açılarla salınan fiziksel sarkaç haline getiriliyor. Eşdeğer basit sarkaç uzunluğu kaç R\'dir?', '2R', ['R', '3R/2', '5R/2'], 'Halkanın merkezine göre I_cm = mR², paralel eksen teoremiyle kenarına göre I = mR² + mR² = 2mR² ve d = R olduğundan L_eş = I/(md) = 2R bulunur.'),
  ('Küçük açılarla salınan bir basit sarkacın ipi, düşeyle 60° açı yapan sabit bir eğik düzleme sürtünmesiz yaslanarak değil, yatay hızla ivmelenen bir aracın tavanına asılıyor. Araç yatay doğrultuda a = (3/4)g sabit ivmesiyle hızlanırken sarkacın yeni periyodu durgun haldeki T periyodunun kaç katı olur?', '2/√5', ['4/5', '√(4/5)', '5/4'], 'Etkin ivme g_etkin = √(g² + (3g/4)²) = (5/4)g olur. Periyot T\' = T·√(g/g_etkin) = T·√(4/5) = (2/√5)T bulunur.'),
  ('Sürtünmesiz yatay düzlemde kütlesi m₁ olan cisim yay ucunda A genliğiyle salınırken üzerine sürtünmeli bir m₂ bloğu konulmuştur. Statik sürtünme katsayısı μ ise m₂ bloğunun m₁ üzerinde kaymadan birlikte salınabileceği en büyük genlik nedir?', 'μ(m₁ + m₂)g/k', ['μm₂g/k', 'μm₁g/k', 'μ(m₁ + m₂)g/(2k)'], 'Üst bloğa etkiyen maksimum sürtünme ivmesi a_max = μg olmalıdır. Sistem ivmesi a_max = kA/(m₁ + m₂) olduğundan A_max = μ(m₁ + m₂)g/k bulunur.'),
  ('Kütlesi M ve yarıçapı R olan bir gezegenin yüzeyinden kaçış hızının yarısı büyüklüğündeki (v₀ = v_kaçış/2) hızla dikey olarak yukarı fırlatılan bir cismin gezegen yüzeyinden çıkabileceği maksimum yükseklik kaç R\'dir?', 'R/3', ['R/2', 'R', 'R/4'], 'v₀² = GM/(2R) olur. Enerji korunumu (1/2)mv₀² - GMm/R = -GMm/(R+h) denkleminden -3GM/(4R) = -GM/(R+h) bulunur; R + h = 4R/3 ve h = R/3 elde edilir.'),
  ('Eliptik bir yörüngede Güneş etrafında dolanan gezegenin günberi uzaklığı r_p ve günöte uzaklığı r_a\'dır. Bu gezegenin yörünge periyodunun bağlı olduğu yarı büyük eksen a, r_p ve r_a cinsinden nasıl ifade edilir?', '(r_p + r_a)/2', ['√(r_p·r_a)', '2r_p·r_a/(r_p + r_a)', '(r_a - r_p)/2'], 'Elipsin büyük eksen uzunluğu günberi ve günöte uzaklıklarının toplamı 2a = r_p + r_a olduğundan yarı büyük eksen a = (r_p + r_a)/2 olur.'),
  ('Kütleleri M ve 4M olan iki yıldız ortak kütle merkezleri etrafında aralarındaki uzaklık d sabit kalacak biçimde dairesel yörüngelerde dolanmaktadır. Bu ikili yıldız sisteminin ortak yörünge periyodu hangi bağıntıyla verilir?', '2π√(d³/(5GM))', ['2π√(d³/(4GM))', '2π√(d³/(3GM))', '2π√(d³/(GM))'], 'İkili sistemlerde genelleştirilmiş Kepler yasası T² = 4π²d³/[G(M₁+M₂)] şeklindedir; M₁+M₂ = 5M yazıldığında T = 2π√(d³/(5GM)) bulunur.'),
  ('Yarıçapı r₁ olan alçak dairesel yörüngeden yarıçapı r₂ = 3r₁ olan yüksek dairesel yörüngeye Hohmann transferi ile geçen bir uzay aracının transfer süresinin, ilk yörüngedeki tam dolanım periyodu T₁ cinsinden değeri nedir?', '√2·T₁', ['2·T₁', '2√2·T₁', 'T₁/√2'], 'Transfer elipsinin yarı büyük ekseni a = (r₁ + 3r₁)/2 = 2r₁ olur. Tam elips periyodu T_elips = T₁·(a/r₁)^(3/2) = 2√2·T₁ olup transfer yarım elips sürdüğünden t = √2·T₁ bulunur.'),
  ('Dünya\'nın yüzeyinde gelgit oluşturan kütleçekim gradyanı (gelgit ivmesi), gelgite neden olan gök cisminin Dünya\'ya uzaklığı r ile nasıl orantılıdır?', '1/r³ ile', ['1/r² ile', '1/r ile', '1/r⁴ ile'], 'Gelgit kuvveti çekim alanının mesafeye göre türevinden (Δg ≈ 2GMR_Dünya/r³) doğduğu için uzaklığın küpüyle ters orantılıdır.'),
  ('Güneş\'in kütlesi Ay\'ın kütlesinin yaklaşık 27 milyon katı olmasına rağmen Dünya okyanuslarında Ay\'ın oluşturduğu gelgit etkisinin Güneş\'inkinin yaklaşık iki katı olmasının temel sebebi nedir?', 'Gelgit kuvvetinin uzaklığın küpüyle ters orantılı olması', ['Güneş ışınım basıncının çekim kuvvetini yarıya düşürmesi', 'Ay\'ın Dünya\'ya daima aynı yüzünü dönerek rezonans yaratması', 'Güneş\'in plazma yapısının katı Ay\'a göre daha zayıf çekim üretmesi'], 'Gelgit kuvveti M/r³ ile orantılıdır; Güneş yaklaşık 390 kat daha uzak olduğundan 390³ ≈ 5,9·10⁷ faktörü kütle farkını aşar ve Ay\'ın gelgiti baskın çıkar.'),
  ('Beş Lagrange noktasından hangileri iki büyük gök cisminin kütle oranı belirli bir sınırın (yaklaşık 24,96) üzerindeyse küçük sapmalara karşı kararlı denge noktalarıdır?', 'L4 ve L5 noktaları', ['L1 ve L2 noktaları', 'L1, L2 ve L3 noktaları', 'L3 ve L5 noktaları'], 'Doğrusal L1, L2, L3 noktaları eyer tipi kararsız denge noktalarıdır; eşkenar üçgen köşelerindeki L4 ve L5 ise Coriolis etkisiyle kararlılık gösterir.'),
  ('Bir gezegenin çevresinde dairesel yörüngede dolanan doğal bir uydunun, gezegenin gelgit kuvvetleriyle parçalanmadan yaklaşabileceği en küçük yörünge mesafesine ne ad verilir?', 'Roche limiti', ['Schwarzschild yarıçapı', 'Hill küresi sınırı', 'Lagrange geçiş eşiği'], 'Uydunun kendi öz kütleçekiminin ana gezegenin gelgit gerilimine yenik düştüğü kritik mesafe Roche limiti (sınırı) olarak tanımlanır.'),
  ('R yarıçaplı dairesel yörüngede dolanan bir uydunun kinetik enerjisi K kadardır. Uydu yörünge yarıçapı 4R olan başka bir dairesel yörüngeye taşındığında yeni kinetik enerjisi kaç K olur?', 'K/4', ['K/2', 'K/8', 'K/16'], 'Kinetik enerji K = GMm/(2r) ile yarıçapla ters orantılıdır; yarıçap 4 katına çıktığında kinetik enerji K/4 değerine iner.'),
  ('Bir gezegen çevresinde eliptik yörüngede dolanan uzay aracının günberideki mesafesi r, hızı v\'dir. Günötedeki mesafesi 3r ise günötedeki kinetik enerjisinin günberideki kinetik enerjisine oranı nedir?', '1/9', ['1/3', '1/6', '3'], 'Açısal momentum korunumundan v_a/v_p = r_p/r_a = 1/3 olur; kinetik enerji hızın karesiyle orantılı olduğundan E_ka/E_kp = (1/3)² = 1/9 bulunur.'),
  ('Atmosfer sürtünmesinin çok hafif de olsa hissedildiği çok alçak Dünya yörüngesindeki bir uydunun sürtünme etkisiyle irtifa kaybederken çizgisel hızında hangi şaşırtıcı (uydu sürüklenme paradoksu) etki gözlenir?', 'İrtifa düştükçe çizgisel hızı artar', ['İrtifa düştükçe çizgisel hızı sürekli azalır', 'İrtifa düşerken yörünge hızı sabit kalır', 'İrtifa düştükçe açısal hızı sıfıra yaklaşır'], 'Sürtünme toplam enerjiyi azaltıp uyduyu daha küçük yarıçapa çektiğinde kaybedilen potansiyel enerjinin yarısı ısıya, yarısı kinetik enerjiye dönüşür ve v = √(GM/r) artar.'),
  ('Yarıçapı R olan bir gezegenin yüzeyinden 3R yüksekliğe çıkarılan m kütleli bir uydunun kütleçekim potansiyel enerjisindeki artış (ΔU), yüzeydeki çekim ivmesi g cinsinden nedir?', '(3/4)mgR', ['(1/4)mgR', '3mgR', '(4/3)mgR'], 'ΔU = -GMm/(4R) - (-GMm/R) = (3/4)GMm/R olur; GM = gR² yazıldığında ΔU = (3/4)mgR elde edilir.'),
  ('Uzunluğu L ve kütlesi m olan homojen ince bir çubuk, tam ortasından değil de bir ucundan L/4 uzaklıktaki bir noktadan menteşelenerek düşey düzlemde küçük açılarla salınan fiziksel sarkaç yapılıyor. Eşdeğer basit sarkaç uzunluğu kaç L\'dir?', '7L/12', ['2L/3', 'L/2', '5L/12'], 'd = L/2 - L/4 = L/4 olur. Paralel eksen teoremiyle I = (1/12)mL² + m(L/4)² = (7/48)mL² elde edilir; L_eş = I/(md) = (7/48)L²/(L/4) = 7L/12 bulunur.'),
  ('R yarıçaplı homojen ince bir dairesel disk, kenarındaki bir noktadan çivilenerek kendi düzlemi içinde küçük açılarla salınmaktadır. Bu fiziksel sarkacın eşdeğer basit sarkaç uzunluğu kaç R\'dir?', '3R/2', ['2R', 'R', '5R/4'], 'Diskin merkezine göre I_cm = (1/2)mR², kenara göre I = (1/2)mR² + mR² = (3/2)mR² ve d = R olduğundan L_eş = I/(md) = 3R/2 olur.'),
  ('Fiziksel sarkaç olarak kullanılan homojen ince bir çubuğun (uzunluk L) küçük salınımlarda minimum periyoda sahip olabilmesi için asılma ekseninin kütle merkezinden uzaklığı (d) ne olmalıdır?', 'L/(2√3)', ['L/2', 'L/4', 'L/√2'], 'L_eş = (I_cm/(md)) + d ifadesi d = √(I_cm/m) = k_j (jirasyon yarıçapı) olduğunda minimum olur; çubuk için I_cm = mL²/12 olduğundan d = L/(2√3) bulunur.'),
  ('Kütlesi M ve yarıçapı R olan sabit yoğunluklu bir diskin kenarından değil, merkezinden geçen düşey bir tele asılarak yatay düzlemde burulma salınımı yapması sağlanıyor. Telin burulma sabiti κ ise bu burulma sarkacının periyodu hangi bağıntıyla verilir?', '2π√(MR²/(2κ))', ['2π√(MR²/κ)', '2π√(2MR²/κ)', '2π√(MR²/(4κ))'], 'Burulma sarkacında T = 2π√(I/κ) olup diskin simetri eksenine göre eylemsizlik momenti I = (1/2)MR² olduğundan T = 2π√(MR²/(2κ)) elde edilir.'),
  ('Sürtünmesiz yatay düzlemde kütlesi 2m ve 6m olan iki blok, yay sabiti k olan kütlesiz bir yayın iki ucuna bağlanmıştır. Yay sıkıştırılıp serbest bırakıldığında sistemin salınım açısal frekansı ne olur?', '√(2k/(3m))', ['√(k/(8m))', '√(k/(2m))', '√(4k/(3m))'], 'İki kütleli yay sisteminde indirgenmiş kütle μ = (m₁m₂)/(m₁+m₂) = (12m²)/(8m) = (3/2)m olur; ω = √(k/μ) = √(2k/(3m)) bulunur.'),
  ('Bir U borusu içindeki sürtünmesiz ve sıkıştırılamaz sıvı sütununun toplam uzunluğu L kadardır. Bir koldan hafifçe bastırılıp bırakılan sıvı sütunu düşey doğrultuda basit harmonik hareket yaptığında periyodu ne olur?', '2π√(L/(2g))', ['2π√(L/g)', '2π√(2L/g)', '2π√(L/(4g))'], 'Sıvı bir kolda x inip diğerinde x yükselince seviye farkı 2x olur; geri çağırıcı ağırlık F = -(2ρAx)g ve toplam kütle m = ρAL olduğundan a = -(2g/L)x ve T = 2π√(L/(2g)) bulunur.'),
  ('Su yüzeyinde dik olarak yüzen düzgün kesitli silindirik bir tahta bloğun su içinde batmış durumdaki denge yüksekliği h kadardır. Blok düşey olarak hafifçe bastırılıp serbest bırakıldığında (su direnci ihmal) salınım periyodu ne olur?', '2π√(h/g)', ['2π√(2h/g)', '2π√(h/(2g))', '2π√(3h/g)'], 'Dengede m = ρ_su·A·h\'dir; x kadar ek batmada geri çağırıcı kaldırma kuvveti ΔF = -ρ_su·A·g·x olduğundan a = -(g/h)x ve T = 2π√(h/g) bulunur.'),
  ('Sönümlü harmonik harekette m·x\'\' + b·x\' + k·x = 0 denklemini sağlayan sistemin kritik sönümlenme göstermesi için sönümleme katsayısı b değeri m ve k cinsinden ne olmalıdır?', '2√(km)', ['√(km)', '√(km)/2', '4√(km)'], 'Karakteristik denklem mr² + br + k = 0\'ın diskriminantı Δ = b² - 4mk = 0 koşulunu sağladığında kritik sönümlenme oluşur; buradan b = 2√(km) bulunur.'),
  ('Zorlamalı ve zayıf sönümlü bir harmonik osilatörde dış kuvvetin frekansı ω_d, sistemin doğal frekansı ω₀\'dan çok büyük (ω_d >> ω₀) yapılırsa cismin yer değiştirmesi ile dış kuvvet arasındaki faz farkı hangi değere yaklaşır?', 'π radyan (180°)', ['0 radyan (0°)', 'π/2 radyan (90°)', 'π/4 radyan (45°)'], 'Çok yüksek uyarım frekanslarında eylemsizlik terimi baskın çıkar ve x(t) ile dış kuvvet F(t) tam ters fazlı (180° faz farkı) hale gelir.'),
  ('Zayıf sönümlü bir harmonik osilatörün doğal frekansı ω₀ iken sönümleme oranı ζ küçük bir pozitif sayıdır. Sistemin serbest salınım yaparken gözlenen sönümlü açısal frekansı ω_d, ω₀ ile nasıl karşılaştırılır?', 'ω_d = ω₀√(1 - ζ²) olup ω₀\'dan küçüktür', ['ω_d = ω₀√(1 + ζ²) olup ω₀\'dan büyüktür', 'ω_d = ω₀ olup sönümlemeden etkilenmez', 'ω_d = ω₀·ζ olup sıfıra çok yakındır'], 'Sönümleme salınımı yavaşlattığı için sönümlü açısal frekans ω_d = √(ω₀² - (b/(2m))²) = ω₀√(1 - ζ²) şeklinde doğal frekanstan biraz küçüktür.'),
  ('Dünya çevresinde r yarıçaplı dairesel yörüngede v₀ hızıyla dolanan bir uzay aracı, anlık bir itkiyle yarı büyük ekseni 2r olan bir eliptik yörüngeye geçmek istiyor. İtki noktasında (yerberide) yeni hızı v₀\'ın kaç katı olmalıdır?', '√(3/2)', ['√2', '2', '√(5/4)'], 'Vis-viva denkleminde a = 2r yazıldığında v² = GM(2/r - 1/(2r)) = (3/2)GM/r = (3/2)v₀² elde edilir; böylece v = √(3/2)·v₀ olur.'),
  ('Eliptik bir yörüngede dolanan gezegenin günberi ve günöte hızları sırasıyla v_p ve v_a\'dır. Bu gezegenin yörünge dış merkezliği e, hızlar cinsinden nasıl ifade edilir?', '(v_p - v_a)/(v_p + v_a)', ['(v_p + v_a)/(v_p - v_a)', '(v_p - v_a)/(2v_p)', '√(v_p/v_a) - 1'], 'v_p/v_a = r_a/r_p = (1+e)/(1-e) eşitliği e için çözüldüğünde e = (v_p - v_a)/(v_p + v_a) elde edilir.'),
  ('R yarıçaplı dairesel yörüngede dolanan bir uydunun Hohmann transferiyle 4R yarıçaplı dairesel yörüngeye geçirilmesi planlanıyor. Transfer elipsinin dış merkezliği e kaçtır?', '0,6', ['0,5', '0,75', '0,4'], 'Transfer elipsinde r_p = R ve r_a = 4R olduğundan a = 2,5R ve e = (r_a - r_p)/(r_a + r_p) = (4R - R)/(4R + R) = 3/5 = 0,6 olur.'),
  ('Güneş çevresinde 1 AB yarıçaplı dairesel yörüngedeki Dünya\'dan 1,52 AB yarıçaplı yaklaşık dairesel yörüngedeki Mars\'a yapılacak tek yönlü bir Hohmann transferinin süresi Dünya yılı cinsinden yaklaşık kaç aydır? (1,26^(3/2) ≈ 1,414 alınız.)', 'Yaklaşık 8,5 ay', ['Yaklaşık 3,5 ay', 'Yaklaşık 17 ay', 'Yaklaşık 24 ay'], 'Transfer yarı büyük ekseni a = (1 + 1,52)/2 = 1,26 AB\'dir; yarım periyot t = (1/2)·1,26^(3/2) ≈ 0,707 yıl ≈ 8,5 ay sürer.'),
  ('Bir gezegenin çevresinde dairesel yörüngede dolanan bir uyduya gezegen merkezine göre anlık radyal dışa doğru (hız vektörüne dik) bir hız bileşeni eklense bile yeni yörüngesinin elips kalabilmesi için toplam enerjisi ne olmalıdır?', 'Negatif kalmalıdır', ['Sıfır olmalıdır', 'Pozitif olmalıdır', 'Başlangıç kinetik enerjisine eşit olmalıdır'], 'Koni kesiti yörüngelerde bağlı eliptik yörünge için temel koşul toplam mekanik enerjinin negatif (E < 0) olmasıdır.'),
  ('Homojen ve içi boş küresel bir kabuğun (kütle M, yarıçap R) içindeki herhangi bir noktada bulunan m kütleli bir test parçacığına kabuğun uyguladığı net kütleçekim kuvveti ve o bölgedeki kütleçekim potansiyeli nasıldır?', 'Kuvvet sıfır, potansiyel sabit ve -GM/R\'dir', ['Kuvvet sıfır, potansiyel de her yerde sıfırdır', 'Kuvvet merkezden uzaklıkla artar, potansiyel değişkendir', 'Kuvvet sabit -GMm/R², potansiyel sıfırdır'], 'Newton\'un kabuk teoremine göre küresel kabuk içinde çekim alanı her noktada sıfırdır; potansiyel ise yüzeydeki değeri olan -GM/R\'ye eşit ve sabittir.'),
  ('Yarıçapı R ve kütlesi M olan homojen bir küreden, merkeze teğet olacak biçimde R/2 yarıçaplı küresel bir oyuk çıkarılıyor. Kalan parçanın kütlesi ilk kütlenin kaçta kaçıdır?', '7/8', ['3/4', '1/2', '5/8'], 'Oyuğun yarıçapı R/2 olduğundan hacmi ve kütlesi (1/2)³ = 1/8 oranındadır; kalan kısım 1 - 1/8 = 7/8 kütleli olur.'),
  ('Kütleçekim etkisi altında iki gezegenin yörüngesi incelenirken Dünya\'nın Güneş\'ten uzaktaki kaçış hızı ile kendi yüzeyinden kaçış hızı karşılaştırılır. Dünya\'nın yörünge hızı ~30 km/s olduğuna göre, Dünya\'nın çekimi yok sayılsa Dünya yörüngesindeki bir aracın Güneş Sistemi\'nden tamamen kaçması için yaklaşık kaç km/s hıza ulaşması gerekir?', 'Yaklaşık 42 km/s', ['Yaklaşık 11,2 km/s', 'Yaklaşık 60 km/s', 'Yaklaşık 21 km/s'], 'Güneş\'ten kaçış hızı dairesel yörünge hızının √2 katıdır: 30·√2 ≈ 42,4 km/s elde edilir.'),
  ('Bir gezegenin ekvatorundaki kendi ekseni etrafındaki dönüş periyodu giderek kısalırsa, ekvatorda duran bir cismin ağırlıksız hale gelip yüzeyden kopma sınırına ulaşması için gezegenin kritik açısal hızı ω_kritik ne olmalıdır?', '√(g/R)', ['√(2g/R)', '√(g/(2R))', '√(gR)'], 'Ekvatorda normal kuvvet N = mg - mω²R sıfırlandığında mω²R = mg eşitliğinden ω_kritik = √(g/R) bulunur.'),
  ('R yarıçaplı bir gezegenin merkezinden r > R uzaklıktaki iki noktasal cisimden biri diğerinin etrafında dairesel yörüngede dönerken bir uzay aracının yörüngesi hiperbolik ise bu uzay aracının toplam mekanik enerjisi E ve dış merkezliği e için hangisi doğrudur?', 'E > 0 ve e > 1', ['E = 0 ve e = 1', 'E < 0 ve 0 < e < 1', 'E < 0 ve e = 0'], 'Serbest kaçış yapan hiperbolik geçiş yörüngelerinde toplam mekanik enerji pozitiftir ve koni kesitinin dış merkezliği 1\'den büyüktür.'),
  ('Güneş-Dünya sisteminde L4 ve L5 Lagrange noktaları, Güneş ve Dünya\'yı birleştiren doğruya göre nasıl bir geometrik yerleşime sahiptir?', 'Güneş ve Dünya ile birer eşkenar üçgen oluşturacak biçimde 60° önde ve 60° geride', ['Güneş ve Dünya doğrusu üzerinde Dünya\'nın tam önünde ve arkasında', 'Dünya\'nın yörüngesine tam 90° dik kutup ekseni üzerinde', 'Güneş\'in tam arkasında ve Dünya\'nın tam ortasında 180° açıyla'], 'L4 Dünya yörüngesinde 60° ileride, L5 ise 60° geride yer alır ve her ikisi de Güneş ve Dünya ile eşkenar üçgen kurar.'),
  ('Kütleleri m olan üç özdeş yıldız, kenar uzunluğu d olan bir eşkenar üçgenin köşelerinde bulunup ortak kütle merkezleri etrafında sabit açısal hızla dairesel yörüngede dönmektedir. Her bir yıldızın çizgisel hızının büyüklüğü nedir?', '√(Gm/d)', ['√(3Gm/d)', '√(Gm/(3d))', '√(2Gm/d)'], 'Bir yıldıza diğer ikisinin uyguladığı net çekim F_net = √3·Gm²/d² olur. Dönme yarıçapı r = d/√3 olduğundan mv²/(d/√3) = √3·Gm²/d² denkleminde √3\'ler sadeleşir ve v = √(Gm/d) bulunur.'),
  ('Merkezi bir gezegen etrafında dairesel yörüngede dolanan bir uydunun kütlesi m, yarıçapı r\'dir. Bu uydunun yörünge yarıçapı sabit kalırken kütlesi 2m yapılırsa bağlanma enerjisi ve yörünge periyodu nasıl değişir?', 'Bağlanma enerjisi iki katına çıkar, periyot değişmez', ['Hem bağlanma enerjisi hem periyot iki katına çıkar', 'Bağlanma enerjisi değişmez, periyot yarıya iner', 'Bağlanma enerjisi dört katına çıkar, periyot değişmez'], 'Bağlanma enerjisi E_b = GMm/(2r) uydu kütlesiyle doğru orantılı olduğundan 2 katına çıkar; periyot T = 2π√(r³/(GM)) uydu kütlesinden bağımsızdır.'),
  ('Yerçekimi ivmesinin g olduğu bir gezegenin yüzeyinden fırlatılan bir cismin fırlatılış hızı kaçış hızının √3/2 katıdır. Cismin gezegen merkezinden ulaşabileceği en büyük uzaklık, gezegenin yarıçapı R\'nin kaç katı olur?', '4R', ['2R', '3R', '8R'], 'v₀² = (3/4)·(2GM/R) = 3GM/(2R) olur. Enerji korunumu (1/2)mv₀² - GMm/R = -GMm/r_max => (3/4 - 1)GM/R = -GM/r_max => -1/(4R) = -1/r_max ve r_max = 4R bulunur.'),
  ('Bir gezegenin çevresinde alçak dairesel yörüngeden çok yüksek dairesel yörüngeye geçişte, hedef yarıçap başlangıç yarıçapının yaklaşık 11,94 katından büyük olduğunda iki itkili Hohmann transferinden daha az toplam hız değişimi (Δv) gerektiren üç itkili transfer manevrası hangisidir?', 'Bi-eliptik (çift eliptik) transfer', ['Doğrudan radyal itki transferi', 'Ters yönlü kutup transferi', 'Tek itkili dairesel spiral'], 'Çok büyük yarıçap oranlarında (r₂/r₁ > 11,94) önce çok uzak bir günöteye çıkıp küçük bir itkiyle yerberi yükseltip sonra frenleme yapan bi-eliptik transfer Hohmann\'dan daha az Δv harcar.'),
  ('Oberth etkisine göre bir roket motorunun aynı miktarda yakıt yakarak uzay aracının toplam mekanik enerjisine en büyük katkıyı (ΔE) sağlayabilmesi için motorun yörüngenin hangi noktasında ateşlenmesi en verimlidir?', 'Hızın en büyük olduğu günberi (yerberi) noktasında', ['Hızın en küçük olduğu günöte (yeröte) noktasında', 'Yarı küçük eksen üzerindeki ortalama hız noktasında', 'Gezegenin çekim alanından tamamen çıkıldıktan sonra'], 'Kinetik enerji değişimi ΔE_k ≈ m·v·Δv olduğundan roketin aynı hız artışı Δv\'yi hızın en yüksek olduğu yerberide (derin kütleçekim kuyusunda) vermesi en fazla enerji kazandırır.'),
  ('Yüzeyinde çekim ivmesi g olan R yarıçaplı küresel bir gezegende, merkeze uzaklığı R/2 olan derin bir maden kuyusunun tabanındaki kütleçekim potansiyeli kaç gR olur? (Homojen küre varsayımıyla, sonsuzda U = 0)', '-(11/8)gR', ['-(3/2)gR', '-(1/2)gR', '-(7/8)gR'], 'Homojen küre içinde potansiyel V(r) = -(GM/(2R³))(3R² - r²) olup r = R/2 için V = -(GM/(2R))(3 - 1/4) = -(11/8)(GM/R) = -(11/8)gR bulunur.'),
  ('İki farklı uydu aynı gezegen etrafında dolanmaktadır: Birinci uydu R yarıçaplı çemberde, ikinci uydu ise günberi uzaklığı R ve günöte uzaklığı 3R olan elipste hareket etmektedir. İkinci uydunun periyodunun birinci uydunun periyoduna oranı nedir?', '2√2', ['2', '4', '√2'], 'Elipsin yarı büyük ekseni a = (R + 3R)/2 = 2R\'dir. Kepler\'in 3. yasasıyla T₂/T₁ = (a/R)^(3/2) = 2^(3/2) = 2√2 bulunur.'),
  ('Bir yayın ucundaki m kütleli cisim yatay sürtünmesiz düzlemde basit harmonik hareket yaparken bir tam periyot boyunca zaman ortalaması alınan kinetik enerji ⟨E_k⟩ ile zaman ortalaması alınan potansiyel enerji ⟨E_p⟩ arasındaki ilişki nedir?', 'Birbirine eşittir ve her biri toplam enerjinin yarısıdır', ['Ortalama kinetik enerji, ortalama potansiyel enerjinin iki katıdır', 'Ortalama potansiyel enerji, ortalama kinetik enerjinin üç katıdır', 'Zaman ortalaması alınan her iki enerji de sıfırdır'], 'cos²(ωt) ve sin²(ωt) fonksiyonlarının bir tam periyot üzerindeki ortalaması 1/2 olduğundan ⟨E_k⟩ = ⟨E_p⟩ = E/2 olur.'),
  ('Özdeş iki gezegenin kütlesi M ve yarıçapı R olup aralarındaki merkezden merkeze uzaklık 4R iken durgun halden serbest bırakılıyorlar. Yalnızca karşılıklı kütleçekimleriyle birbirine yaklaşarak yüzeyleri tam temas ettiği anda her bir gezegenin hızı ne olur?', '√(GM/(4R))', ['√(GM/(2R))', '√(GM/R)', '√(GM/(8R))'], 'Başlangıç potansiyeli -GM²/(4R), temas anında (merkezler arası 2R) potansiyel -GM²/(2R) olur. Enerji korunumu 2·(1/2)Mv² = GM²/(4R) denkleminden v = √(GM/(4R)) bulunur.'),
];
